/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
'use strict';
const D=globalThis.RA.D;
const Q=(s,prompt,answer,wrong1,wrong2,explain,errorType='meaning')=>({s,prompt,answer,wrong1,wrong2,explain,errorType});
const M=(wrong,right,reason,errorType='meaning')=>({errorType,wrong,right,reason});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:( {
  'or else':'Etymonline: https://www.etymonline.com/word/or; https://www.etymonline.com/word/else',
  'ordinary people':'Etymonline: https://www.etymonline.com/word/ordinary; https://www.etymonline.com/word/people',
  'originating in':'Etymonline: https://www.etymonline.com/word/originate; https://www.etymonline.com/word/in',
  'orleans':'City of Orléans: https://www.orleans.fr/fileadmin/orleans/MEDIA/kiosque/ville_art_histoire/vdh_trough_centuriesGB.pdf',
  'orogeny':'Etymonline: https://www.etymonline.com/word/orogeny',
  'ordnance':'Etymonline: https://www.etymonline.com/word/ordnance',
  'ordinance':'Etymonline: https://www.etymonline.com/word/ordinance',
  'oriental':'Etymonline: https://www.etymonline.com/word/oriental; APA Inclusive Language Guide: https://www.apa.org/about/apa/equity-diversity-inclusion/language-guide.pdf'
}[w]||('Etymonline: https://www.etymonline.com/word/'+w.toLowerCase().replaceAll(' ','-')) )});
const P=(w,origin,contexts,mistake,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(contexts)?contexts:[contexts],mistakes:[mistake],quiz:qs.map((q,i)=>({id:w+'.q'+(i+1),senseId:w+'.s'+q.s,prompt:q.prompt,answer:q.answer,options:[q.answer,q.wrong1,q.wrong2],explain:q.explain,errorType:q.errorType,type:'辨义与用法'}))});
P('opposite','From Latin oppositus, past participle of opponere “set against,” from ob- “against” + ponere “put”; it can describe facing positions, contrary qualities, a preposition of location, or an antonym.',[C('opposite.s1','通用','The two cottages stood on opposite sides of the narrow lane, facing one another across the road.','两栋小屋分别坐落在小巷两侧，隔着道路彼此相望。','The two cottages stood on opposite sides / of the narrow lane / facing one another / across the road.','opposite.s1 作形容词，表示在另一边并面对着。','两栋房屋隔路相望。'),C('opposite.s2','通用','Her reaction was the opposite of mine: she welcomed the delay while I worried about missing the train.','她的反应和我截然相反：她欢迎延期，我却担心赶不上火车。','Her reaction was the opposite of mine / she welcomed the delay / while I worried / about missing the train.','opposite.s2 表示相反的、对立的。','一人欢迎延期，另一人担心误车，态度相反。'),C('opposite.s3','通用','The pharmacy is opposite the library, directly across the square from its main entrance.','药房在图书馆对面，正好隔着广场与正门相望。','The pharmacy is opposite the library / directly across the square / from its main entrance.','opposite.s3 作介词，表示在某处另一边并面向它。','药房与图书馆隔广场相对。'),C('opposite.s4','通用','“Generous” is the opposite of “selfish,” so the two words express contrasting qualities.','generous（慷慨的）是selfish（自私的）的反义词，因此两个词表达相反的品质。','“Generous” is the opposite of “selfish” / so the two words / express contrasting qualities.','opposite.s4 作名词，指对立的人或物，也可指反义词。','两个形容词意思相反。')],M('The pharmacy was opposite the library because it stood beside the library on the same side of the square.','The pharmacy was opposite the library because it stood across the square facing it.','opposite 表示在对面相望；同侧相邻应说 beside。','distinction'),[Q(1,'Where were the cottages in relation to the lane?','On facing sides of it.','Beside one another on the same side.','Far away on an unrelated road.','opposite.s1 描述隔路相望的位置。'),Q(2,'How did her reaction compare with mine?','It was contrary to mine.','It was exactly the same.','It happened several years earlier.','opposite.s2 指完全相反的态度。','distinction'),Q(3,'Where is the pharmacy?','Across the square from the library.','Inside the library.','Behind the library on the same side.','opposite.s3 作介词表示在……对面。'),Q(4,'What is the opposite of generous?','selfish','patient','ordinary','opposite.s4 作名词，指反义词。','meaning')]);
P('oppositely','From opposite + -ly; the adverb means on the other side or in a contrary direction or manner.',C('oppositely.s1','科学','The two magnetic needles were arranged oppositely, with their north poles pointing away from each other.','两根磁针被反向摆放，北极彼此背离。','The two magnetic needles were arranged oppositely / with their north poles / pointing away from each other.','oppositely 表示朝相反方向或以相反方式。','副词修饰 arranged，说明两根磁针的摆放方向相反。','word-formation'),M('The needles were arranged oppositely with both north poles pointing in exactly the same direction.','The needles were arranged identically with both north poles pointing in the same direction.','指向完全相同不符合 oppositely，需用 identically。','distinction'),[Q(1,'Which way did the two north poles point?','Away from each other.','Toward one another.','Straight down into the table.','oppositely.s1 表示方向相反。'),Q(1,'What does oppositely modify in the example?','The way the needles were arranged.','The number of needles.','The strength of the magnets.','副词说明摆放方式。','grammar'),Q(1,'Which action is done oppositely?','Two arrows point in opposite directions.','Two arrows overlap and point the same way.','An arrow is placed in a box.','oppositely 描述相反方向。','meaning'),Q(1,'How is oppositely formed?','opposite + -ly','opposite + plural -s','oppose + past -ed','-ly forms the adverb oppositely.','word-formation')]);
P('opposition','From Old French opposition, from Latin oppositionem, noun of action from opponere “set against”; it can mean resistance to a proposal or the parties not in government.',[C('opposition.s1','通用','The plan to close the neighborhood clinic met strong opposition from patients and nearby residents.','关闭社区诊所的计划遭到患者和附近居民的强烈反对。','The plan to close the neighborhood clinic / met strong opposition / from patients and nearby residents.','opposition.s1 指对计划或另一力量的强烈反对。','患者和居民公开反对关闭诊所。'),C('opposition.s2','政治','After the election, the opposition questioned the new government’s budget during the first parliamentary debate.','选举结束后，反对党在第一次议会辩论中质疑新政府的预算。','After the election / the opposition questioned the new government’s budget / during the first parliamentary debate.','opposition.s2 指不执政的政党或在野一方。','在议会监督新政府的是在野党。')],M('The opposition supported every part of the proposal and raised no objections during the debate.','The opposition challenged the proposal during the debate.','反对方对提案提出异议，不能说全盘支持且无反对。','distinction'),[Q(1,'Who opposed closing the clinic?','Patients and nearby residents.','The clinic’s empty building.','Only the new government’s cabinet.','opposition.s1 是对计划的反对。'),Q(2,'What did the opposition question after the election?','The new government’s budget.','The clinic’s opening hours only.','The election results from a century ago.','opposition.s2 指在野方监督政府。'),Q(1,'Which phrase is closest to strong opposition?','firm resistance','complete approval','quiet agreement','opposition.s1 表示强烈反对。','meaning'),Q(2,'Which group is the opposition in a parliamentary system?','Parties not forming the government.','The governing cabinet itself.','All civil servants together.','该政治义指不执政的政党。','distinction')]);
P('oppress','From Latin opprimere “press down, overwhelm,” from ob- “against” + premere “press”; it can mean tyrannical treatment or a heavy feeling that weighs on someone.',[C('oppress.s1','政治','The regime used arbitrary arrests and censorship to oppress communities that demanded equal voting rights.','该政权通过任意逮捕和审查，压迫要求平等投票权的社群。','The regime used arbitrary arrests and censorship / to oppress communities / that demanded equal voting rights.','oppress.s1 指以残酷、不公的方式统治或对待人。','逮捕和审查是针对社群的压制手段。'),C('oppress.s2','书面','The uncertainty about her missing brother continued to oppress her long after the search had ended.','寻找失踪弟弟的结果始终未明，这种不确定感在搜寻结束很久后仍令她心情沉重。','The uncertainty about her missing brother / continued to oppress her / long after the search had ended.','oppress.s2 可指忧虑或不适感使人难以放松。','持续的不确定感给她心理重压。')],M('The authorities oppressed the protestors by protecting their right to speak and allowing them to organize freely.','The authorities oppressed the protestors by arresting organizers and censoring their demands.','保护表达与组织自由不是压迫；逮捕和审查才构成压制。','distinction'),[Q(1,'How did the regime oppress the communities?','Through arbitrary arrests and censorship.','By granting equal voting rights.','By ending all restrictions.','oppress.s1 描述残酷不公的统治。'),Q(2,'What continued to oppress her after the search?','Uncertainty about her brother.','A successful reunion.','A new voting law.','oppress.s2 指心理上的沉重压抑。'),Q(1,'Which action could oppress a minority group?','Denying it equal legal rights.','Protecting its right to vote.','Inviting it to a fair hearing.','压迫涉及不公的限制或对待。','meaning'),Q(2,'How does the second use of oppress differ from the first?','It describes a distressing feeling rather than political mistreatment.','It means the opposite of worry.','It refers to a government arrest only.','oppress 也可描述心理重压。','distinction')]);
P('oppression','From Latin oppressionem, noun of action from opprimere “press down”; it means sustained cruel treatment by those in power or a burdened feeling.',C('oppression.s1','政治','The oral history project recorded how generations endured oppression under laws that denied them land and education.','口述史项目记录了几代人如何在剥夺土地和教育权的法律下忍受压迫。','The oral history project recorded / how generations endured oppression / under laws / that denied them land and education.','oppression 指长期残酷不公的对待，也可指心情沉重的压抑感。','法律长期剥夺群体权利，属于制度性压迫。'),M('The archive described the fair access to land and education as oppression even though no rights were restricted.','The archive described laws denying land and education as oppression.','剥夺基本权利的不公制度才是 oppression，不是公平准入。','distinction'),[Q(1,'What rights were denied under the laws?','Land and education.','The right to attend an archive.','A choice of music only.','oppression.s1 指长期制度性压迫。'),Q(1,'What did the oral history project record?','Generations’ experiences under unjust laws.','A weather report about a storm.','A list of orchestra seats.','口述史记录了人们经历的压迫。','context'),Q(1,'Which phrase best describes oppression?','Sustained cruel treatment by those in power.','A brief disagreement over a menu.','A fair and equal policy.','oppression 通常是长期不公对待。','meaning'),Q(1,'Which word is the noun related to oppress?','oppression','oppressive','oppositely','oppression names the act or condition of oppressing.','word-formation')]);
P('oppressive','From oppress + -ive; it describes cruelly restrictive power or conditions that cause discomfort through heat, weight, or gloom.',C('oppressive.s1','社会','Residents organized a meeting to challenge the oppressive rule that required permits for every public gathering.','居民组织集会，反对那项要求所有公共集会都必须取得许可的压制性规定。','Residents organized a meeting / to challenge the oppressive rule / that required permits / for every public gathering.','oppressive.s1 表示以严酷权力限制人的，或令人难以忍受的环境。','规定严格限制公共集会。'),M('The rule was oppressive because it guaranteed open access to meetings and imposed no restrictions.','The rule was oppressive because it required permits for every public gathering.','无门槛开放不是压制性限制，普遍许可要求才构成限制。','distinction'),[Q(1,'What made the rule oppressive?','It required permits for every public gathering.','It guaranteed unrestricted public access.','It canceled all permit requirements.','oppressive.s1 指压制性的规则。'),Q(1,'Which weather could be described as oppressive?','Humid heat that makes it hard to breathe comfortably.','A mild, breezy afternoon.','A clear sky with a cool breeze.','oppressive 也可形容令人难受的闷热。','meaning'),Q(1,'What does -ive form in oppressive?','An adjective related to the action or quality of oppressing.','A plural noun.','A past-tense verb.','oppress + -ive forms an adjective.','word-formation'),Q(1,'What did residents do in response to the rule?','They organized a meeting to challenge it.','They applied for a weather forecast.','They canceled the public gathering permanently.','例句说明居民反对压制性规定。','context')]);
P('opt','From Latin optare “choose, wish”; it means to select one possibility or, in opt out, decide not to participate.',[C('opt.s1','通用','After comparing the routes, the hikers opted for the shaded trail that followed the river.','比较路线后，徒步者选择了沿河的林荫小径。','After comparing the routes / the hikers opted for the shaded trail / that followed the river.','opt.s1 指从多个可能中选择一种。','opted for 后接被选中的路线。'),C('opt.s2','通用','Employees may opt out of the optional survey without giving a reason.','员工可以不说明理由而退出这项自愿调查。','Employees may opt out of the optional survey / without giving a reason.','opt.s2 常用于 opt out，表示决定不参加。','out 表示退出或不参与。')],M('The hikers opted for the riverside trail by refusing to choose any route and staying home.','The hikers opted for the riverside trail after comparing the available routes.','opt for 表示选定某项；不选择并留在家里不符合句意。','collocation'),[Q(1,'Which route did the hikers choose?','The shaded trail by the river.','The steep road beside the highway.','No route; they stayed home.','opt.s1 表示选定一条路线。'),Q(2,'What may employees do with the survey?','Choose not to take part.','Be required to complete it.','Opt for a different job.','opt out of 表示决定退出。','collocation'),Q(1,'Which pattern means “choose”?','opt for a plan','opt out of a plan','opt down a plan','opt for introduces the chosen possibility.','collocation'),Q(2,'Which pattern means “decline to participate”?','opt out of the survey','opt for the survey','opt at the survey','opt out is the participation-withdrawal phrase.','meaning')]);
P('optic','From Greek optikos “of sight,” from optos “seen”; the adjective relates either to the eye/vision or to the science of light.',[C('optic.s1','医学','The surgeon checked the optic nerve because the patient reported a sudden loss of vision in one eye.','患者报告一只眼睛突然视力下降后，外科医生检查了视神经。','The surgeon checked the optic nerve / because the patient reported / a sudden loss of vision / in one eye.','optic.s1 表示眼的或视觉的。','optic nerve 是传递视觉信息的神经。'),C('optic.s2','物理','The lab used an optic sensor to measure how the glass lens bent a narrow beam of light.','实验室用光学传感器测量玻璃透镜如何折射一束窄光。','The lab used an optic sensor / to measure / how the glass lens bent / a narrow beam of light.','optic.s2 表示与光和透镜科学有关。','透镜折射光线属于光学。')],M('The physician called the lens-bending experiment an optic nerve test even though no eye or vision was examined.','The physician called the lens-bending experiment an optics test.','optic nerve 关乎视觉神经；单独研究透镜折光应称光学实验。','distinction'),[Q(1,'Why did the surgeon examine the optic nerve?','The patient had sudden vision loss.','The lens bent a light beam.','The patient wanted a new timetable.','optic.s1 与视觉器官有关。'),Q(2,'What did the lab measure with its optic sensor?','How the lens bent light.','How a person’s nerve transmitted sound.','How many routes hikers chose.','optic.s2 指光学相关的测量。'),Q(1,'Which phrase refers to a structure in the eye?','optic nerve','optic beam only','optic calendar','optic can mean related to the eye.','collocation'),Q(2,'Which topic is optical/optic in the scientific sense?','Refraction of light through a lens.','A person’s voting choice.','A political opposition party.','透镜折光是光学内容。','meaning')]);
P('optical','From optic + -al, ultimately from Greek optikos “of sight”; it relates to light, eyes, or vision.',C('optical.s1','科学','The camera’s optical zoom enlarges the image by moving lens elements rather than merely cropping the picture.','相机的光学变焦通过移动镜片放大图像，而不只是裁剪照片。','The camera’s optical zoom enlarges the image / by moving lens elements / rather than merely cropping the picture.','optical 表示与光、眼睛或视觉有关。','镜片移动改变成像，是光学变焦。'),M('The camera advertised digital cropping as optical zoom even though no lens element moved.','The camera advertised lens-based enlargement as optical zoom because its lens elements moved.','光学变焦依靠镜片变化；单纯裁剪属于数字变焦。','distinction'),[Q(1,'How did the camera enlarge the image optically?','By moving lens elements.','By cropping pixels only.','By changing the photograph’s subject.','optical.s1 指光学镜片操作。'),Q(1,'Which device uses optical components?','A telescope lens.','A printed paper list.','A cloth shopping bag.','透镜利用光学原理。','meaning'),Q(1,'What does optical modify in the example?','zoom','hikers','survey','optical is the adjective describing the zoom method.','grammar'),Q(1,'Why is cropping alone not optical zoom?','It changes the image digitally without moving lens elements.','It uses a glass lens to bend light.','It improves the camera’s focus optically.','例句区分镜头变焦和数字裁剪。','distinction')]);
P('optician','From optic + -ian, a person trained to make or sell glasses and contact lenses; opticians fit eyewear, while optometrists test sight and prescribe lenses.',C('optician.s1','通用','The optician adjusted the frames behind the customer’s ears and checked that the lenses sat level.','配镜师调整顾客耳后的镜架，并检查镜片是否平齐。','The optician adjusted the frames / behind the customer’s ears / and checked / that the lenses sat level.','optician 指制作、销售或调试眼镜和隐形眼镜的专业人员。','调整镜架与镜片是配镜师的工作。','word-formation'),M('The shop called the person aligning the eyeglass frames an optician but said the word meant an eye surgeon.','The shop called the person fitting and adjusting the eyeglass frames an optician.','optician 配镜或销售眼镜，不等同于眼科外科医生。','distinction'),[Q(1,'What did the optician adjust?','The eyeglass frames.','The customer’s hearing aid.','The camera’s digital crop.','optician.s1 指配镜专业人员。'),Q(1,'Which task fits an optician?','Fitting contact lenses and eyeglass frames.','Performing heart surgery.','Writing a law about public meetings.','配镜师负责眼镜与隐形眼镜。','meaning'),Q(1,'How does an optician differ from an optometrist in the source?','An optician fits or sells eyewear; an optometrist tests sight and prescribes lenses.','An optician studies mountain formation.','An optometrist only repairs camera lenses.','来源义项区分配镜师与验光师。','distinction'),Q(1,'What did the optician check after adjusting the frames?','That the lenses sat level.','That the hikers chose the right trail.','That the frames were made of paper.','例句说明配镜师检查镜片位置。','context')]);
P('optics','From Greek optikē “the science of sight,” via Latin/French; optics is the branch of physics that studies light and its effects on vision.',C('optics.s1','科学','The class used a prism to study optics and observe how white light separates into a spectrum of colors.','课堂用棱镜学习光学，观察白光如何分解成色谱。','The class used a prism / to study optics / and observe / how white light separates into a spectrum of colors.','optics 指研究光及视觉的科学。','棱镜分光是光学实验。'),M('The lesson called the study of political elections optics because it involved looking at charts.','The lesson called the study of light and lenses optics.','optics 是光学，不是泛指“看图表”。','word-choice'),[Q(1,'What did the class observe with a prism?','White light separating into a spectrum.','A political party changing its platform.','An orchard growing fruit.','optics.s1 指光的现象。'),Q(1,'Which topic belongs to optics?','How a lens focuses light.','How a city passes a law.','How a choir rehearses a concert.','透镜和光的行为属于光学。','meaning'),Q(1,'What does optics study?','Light and its effects on vision.','Only the history of political opposition.','Only the sale of eyeglasses.','optics 是研究光与视觉的学科。'),Q(1,'Which equipment is used in the example?','A prism.','A ballot box.','A flowerpot.','课堂通过棱镜观察光谱。','context')]);
P('optimal','From optimum + -al, ultimately from Latin optimus “best”; it means best or most favorable among available conditions.',C('optimal.s1','科学','The seedlings grew best at the optimal temperature identified in the greenhouse trial.','幼苗在温室试验测出的最佳温度下生长得最好。','The seedlings grew best / at the optimal temperature / identified in the greenhouse trial.','optimal 表示现有条件中最好的或最有利的。','试验找到了最利于幼苗生长的温度。'),M('The report called a temperature that killed the seedlings optimal for their growth.','The report called the temperature that produced the strongest growth optimal.','optimal 表示最有利条件，不是造成伤害的条件。','distinction'),[Q(1,'At which temperature did the seedlings grow best?','The one identified by the greenhouse trial.','A temperature that killed them.','Any temperature regardless of results.','optimal.s1 指最有利于生长的温度。'),Q(1,'Which phrase naturally uses optimal?','optimal conditions','optimal mistake','optimal yesterday','optimal commonly describes best conditions.','collocation'),Q(1,'What does optimal mean?','Best possible or most favorable.','Merely average.','Completely unnecessary.','optimal is the best among available options.','meaning'),Q(1,'How did researchers identify the optimal temperature?','Through a greenhouse trial.','By guessing without observing plants.','By asking a political opposition party.','例句指出最佳温度由试验确定。','context')]);
P('optimism','From French optimisme, from Latin optimus “best”; it means a tendency to expect good outcomes or the philosophical belief that the world tends toward good.',[C('optimism.s1','心理','Despite the delayed shipment, the project team kept its optimism and prepared a backup plan for launch day.','尽管货运延迟，项目团队仍保持乐观，并为发布日准备了备用方案。','Despite the delayed shipment / the project team kept its optimism / and prepared a backup plan / for launch day.','optimism.s1 指倾向于相信事情会有好结果的乐观态度。','团队仍期待成功，同时作好备用安排。'),C('optimism.s2','哲学','In the seminar, the lecturer contrasted philosophical optimism with pessimism about whether the world is ultimately good.','研讨课上，讲师比较了乐观主义与悲观主义，讨论世界最终是否趋善。','In the seminar / the lecturer contrasted philosophical optimism / with pessimism / about whether the world is ultimately good.','optimism.s2 指认为世界整体趋向于善的一种哲学立场。','这里讨论世界总体性质，是哲学观点而非个人心情。')],M('The team showed optimism by assuming the launch would fail and refusing to prepare any backup.','The team showed optimism by expecting the launch to succeed while preparing a backup.','期待有好结果体现乐观；预防措施并不与乐观矛盾。','distinction'),[Q(1,'How did the team show optimism?','It expected a good outcome and prepared a backup.','It refused to plan because failure was certain.','It canceled the launch before the shipment arrived.','optimism.s1 是对结果抱有积极期待。'),Q(2,'What philosophical question was discussed?','Whether the world is ultimately good.','Whether one shipment was late.','Which team member should lead a meeting.','optimism.s2 是关于世界整体趋善的哲学观点。'),Q(1,'Which person shows optimism?','Someone expects improvement while working on a solution.','Someone assumes nothing can ever improve.','Someone refuses to consider any possibility.','相信有好结果并采取行动体现乐观。','meaning'),Q(2,'What was contrasted with philosophical optimism?','Pessimism.','An optical lens.','A city ordinance.','讲师将 optimism 与 pessimism 对比。','context')]);
P('optimist','From optimism + -ist, a person inclined to expect favorable outcomes or who holds an optimistic outlook.',C('optimist.s1','通用','An optimist, Priya kept applying for research grants after the first two proposals were declined.','普里娅是个乐观者，前两份研究资助申请被拒后仍继续申请。','An optimist / Priya kept applying for research grants / after the first two proposals were declined.','optimist 指倾向于相信事情会有好结果的人。','被拒后继续尝试体现她的积极期待。','word-formation'),M('The article called Priya an optimist because she believed every future attempt was certain to fail.','The article called Priya an optimist because she expected a future attempt might succeed.','认为未来必然失败是悲观态度，不是乐观。','distinction'),[Q(1,'What did Priya do after two rejections?','She continued applying for grants.','She stopped all research permanently.','She joined the opposition party.','optimist.s1 指仍相信可能成功的人。'),Q(1,'Which person is an optimist?','A person who expects a setback can be overcome.','A person certain that every effort will fail.','A person who avoids making any prediction.','乐观者期待事情可能好转。','meaning'),Q(1,'What is an optimist?','A person with an expectation of favorable outcomes.','A device that focuses light.','A rule passed by a town council.','optimist 是人的名词。','word-formation'),Q(1,'Why does Priya continue applying?','She thinks a later proposal may succeed.','She knows grants are never awarded.','She has already received every grant.','例句说明她仍相信未来能获资助。','context')]);
P('optimistic','From optimism + -istic, meaning hopeful or expecting a good result.',C('optimistic.s1','心理','The engineers were optimistic about the repair because the replacement part had passed every bench test.','工程师对修复结果感到乐观，因为替换部件通过了所有台架测试。','The engineers were optimistic about the repair / because the replacement part / had passed every bench test.','optimistic 表示对事情抱有好期望的。','通过测试使团队相信修理会成功。','word-formation'),M('The engineers were optimistic about the repair because they expected the tested part to fail immediately.','The engineers were pessimistic about the repair because they expected the part to fail.','期待立即失败表示悲观，不是乐观。','distinction'),[Q(1,'Why were the engineers optimistic?','The replacement part passed every bench test.','The replacement part was never tested.','They knew the repair had already failed.','optimistic.s1 表示期待积极结果。'),Q(1,'Which sentence is optimistic?','We may solve the problem if we keep testing.','There is no chance anything can improve.','Every attempt is certain to fail.','积极期待仍保留改进的可能。','meaning'),Q(1,'What noun is optimistic related to?','optimism','optician','oppression','optimistic derives from optimism.','word-formation'),Q(1,'Does an optimistic engineer have to ignore risks?','No; optimism can coexist with testing and planning.','Yes; optimism means refusing all evidence.','Yes; optimism means a repair is already complete.','例句中的乐观有测试证据支撑。','distinction')]);
P('optimization','From optimize + -ation, built on optimal; it names the process of improving a system or use of resources toward the best attainable performance.',C('optimization.s1','科技','The software update included database optimization that reduced search time without removing any records.','软件更新包含数据库优化，在未删除记录的情况下缩短了搜索时间。','The software update included database optimization / that reduced search time / without removing any records.','optimization 指改进设计、系统或资源利用的过程。','更新通过优化提高检索效率。','word-formation'),M('The team called deleting half the records without checking the results optimization even though search time increased.','The team called the tested changes optimization because they reduced search time while preserving records.','优化应改进性能或资源使用，盲删且变慢不是优化。','distinction'),[Q(1,'What did the database optimization improve?','Search time.','The number of deleted records.','The color of the office walls.','optimization.s1 是改进系统的过程。'),Q(1,'What did the update preserve?','All records.','Only the fastest result.','The old search delay.','例句明确未删除任何记录。','context'),Q(1,'Which activity is optimization?','Adjusting a route to use less fuel while meeting the same delivery goals.','Removing random data until the system crashes.','Changing a label without changing performance.','优化是改进系统表现或资源使用。','meaning'),Q(1,'How is optimization formed?','optimize + -ation','optimal + plural -s','optician + -ed','-ation forms the process noun optimization.','word-formation')]);
P('optimize','From optimal + -ize, ultimately from Latin optimus “best”; it means to adjust a process or system so it works as well as possible.',C('optimize.s1','科技','The developers optimized the search routine so the app could find local files more quickly on older phones.','开发人员优化了搜索程序，使应用在旧手机上也能更快找到本地文件。','The developers optimized the search routine / so the app could find local files / more quickly / on older phones.','optimize 指调整事物，使其尽可能有效或运行良好。','改进程序让检索速度提升。','word-formation'),M('The team optimized the search routine by adding unnecessary steps that made every query slower.','The team optimized the search routine by removing unnecessary steps that had slowed queries.','优化应改善性能；增加冗余步骤并减速与词义相反。','distinction'),[Q(1,'What did the developers optimize?','The app’s search routine.','The phones’ screen color.','The number of local files deleted.','optimize.s1 表示改进程序运行。'),Q(1,'What was the result of the optimization?','The app found local files faster.','Every search became slower.','The app stopped storing files.','例句说明搜索速度提高。','context'),Q(1,'Which action could optimize a delivery route?','Replanning it to save fuel without missing stops.','Adding unnecessary miles to every trip.','Removing all delivery addresses.','optimize means make a system work as well as possible.','meaning'),Q(1,'What noun names the process of optimizing?','optimization','optimist','optics','optimization is the process noun related to optimize.','word-formation')]);
P('optimum','From Latin optimum, neuter form of optimus “best”; it is an adjective meaning best or most suitable and a noun for the best attainable condition or amount.',[C('optimum.s1','科学','The seedlings produced the strongest roots under optimum light and moisture conditions in the controlled trial.','在受控试验中，幼苗在最适宜的光照和水分条件下长出了最强壮的根。','The seedlings produced the strongest roots / under optimum light and moisture conditions / in the controlled trial.','optimum.s1 作形容词，表示最佳或最适宜的。','试验比较条件后找出最佳生长条件。'),C('optimum.s2','科学','After several trials, the lab identified 18 degrees as the optimum for storing the enzyme.','经过多次试验，实验室确定18度是保存这种酶的最佳温度。','After several trials / the lab identified 18 degrees / as the optimum / for storing the enzyme.','optimum.s2 作名词，指最佳的数量、时间或状态。','18度是多次测试得到的最佳点。')],M('The lab called the temperature that destroyed the enzyme the optimum for storing it.','The lab called the temperature that preserved the enzyme best the optimum for storage.','保存最佳状态的温度才是 optimum；导致酶失活的温度不是。','distinction'),[Q(1,'Under what conditions did the seedlings grow strongest?','Optimum light and moisture.','No light and no moisture.','Any condition without measurement.','optimum.s1 作形容词指最佳条件。'),Q(2,'What was the lab’s optimum storage temperature?','18 degrees.','80 degrees.','No temperature was tested.','optimum.s2 指经测试得到的最佳温度点。','number'),Q(1,'Which sentence uses optimum as an adjective?','They found the optimum route for the delivery.','The optimum was reached at 18 degrees.','They measured an optimum of 18 degrees.','第一句中 optimum 修饰 route。','grammar'),Q(2,'Which sentence uses optimum as a noun?','The lab identified 18 degrees as the optimum.','The optimum light helped the seedlings.','She chose an optimum route.','as the optimum 中 optimum 作名词。','grammar')]);
P('option','From French option, from Latin optionem “choice, free choice,” from optare “choose”; it means a thing available to choose or the act of choosing.',C('option.s1','通用','The travelers had one final option: take the early ferry or wait until the next morning.','旅客只剩最后一个选择：乘早班渡船，或者等到第二天早上。','The travelers had one final option / take the early ferry / or wait until the next morning.','option 指可以选择的事物或可供选择的办法。','句中列出两个可选方案。'),M('The notice said travelers had no option but to choose between the early ferry and waiting until morning.','The notice said travelers had two options: the early ferry or waiting until morning.','“no option but”表示别无选择，与列出多个可选方案矛盾。','distinction'),[Q(1,'What were the travelers’ options?','Take the early ferry or wait until morning.','Drive across a bridge that did not exist.','Cancel the ferry service permanently.','option.s1 指可供选择的办法。'),Q(1,'Which phrase means a possible choice?','a travel option','a travel oppression','a travel orchard','option means a thing that can be chosen.','meaning'),Q(1,'How many plans are listed in the example?','Two.','One hundred.','None.','句子给出乘早班渡船或等待两个方案。','number'),Q(1,'Which sentence uses option correctly?','Buying a pass is one option for the trip.','Buying a pass is one optional.','The pass optioned the traveler yesterday.','option 是名词，可指一种选择。','grammar')]);
P('optional','From option + -al; it means available by choice rather than required, either by a rule or by personal preference.',[C('optional.s1','通用','The final practice set is optional, so students may complete it for extra review but will not lose marks if they skip it.','最后一组练习是选做的，学生可以用来复习；不做也不会扣分。','The final practice set is optional / so students may complete it for extra review / but will not lose marks / if they skip it.','optional.s1 表示可以选做而非必须完成。','跳过练习不扣分，说明它并非强制。'),C('optional.s2','通用','The museum made the guided tour optional and let visitors explore the galleries on their own instead.','博物馆把导览设为自愿参加，允许访客自行参观展厅。','The museum made the guided tour optional / and let visitors explore / the galleries on their own / instead.','optional.s2 指由个人决定、规则不作强制要求的。','访客可以自行决定是否参加导览。')],M('The form described the signature as optional but rejected every application without one.','The form described the signature as required because every application needed one.','若缺少签名就拒收，签名是必需的而非 optional。','distinction'),[Q(1,'What happens if students skip the practice set?','They do not lose marks.','They fail the course automatically.','They must pay a fine.','optional.s1 表示非必做。'),Q(2,'What could museum visitors choose?','Join the tour or explore alone.','Leave only if the guide approves.','Visit only with a required tour.','optional.s2 表示是否参加由个人决定。'),Q(1,'Which activity is optional?','An extra review exercise that can be skipped without penalty.','A required safety evacuation.','A signature needed for an application to be accepted.','optional 指不强制的活动。','meaning'),Q(2,'What does optional contrast with?','required','available by choice','left to personal preference','optional means not required, so required is its opposite.','confusable')]);
P('optometrist','From optometry + -ist, an eye-care professional who tests sight and prescribes corrective lenses.',C('optometrist.s1','通用','The optometrist measured Jonah’s vision and prescribed new lenses after he struggled to read the road signs.','乔纳阅读路牌吃力后，验光师为他测量视力并开了新的镜片处方。','The optometrist measured Jonah’s vision / and prescribed new lenses / after he struggled / to read the road signs.','optometrist 指检查视力并开具镜片处方的专业人员。','测视力和开镜片处方是验光师的工作。','word-formation'),M('The clinic called the person selling frames an optometrist but said that professional only repairs bicycle tires.','The clinic called the eye-care professional who tested vision and prescribed lenses an optometrist.','optometrist 是视力检查专业人员，不是自行车修理工。','distinction'),[Q(1,'What did the optometrist do for Jonah?','Measured his vision and prescribed lenses.','Adjusted a bicycle tire.','Performed a political poll.','optometrist.s1 指检查视力并开镜片处方的人。'),Q(1,'Which task belongs to an optometrist?','Testing eyesight.','Conducting heart surgery.','Selling orchard land only.','验光师负责视力检查。','meaning'),Q(1,'How does an optometrist differ from an optician?','An optometrist tests sight and prescribes lenses; an optician fits or sells eyewear.','An optometrist is a lens itself.','An optician diagnoses all eye diseases as a surgeon.','两种职业的职责不同。','distinction'),Q(1,'Why did Jonah seek eye care?','He struggled to read road signs.','He was choosing an optional class.','He needed an orchestra ticket.','例句说明阅读路牌困难是就诊原因。','context')]);
P('opulence','From Latin opulentia “wealth, abundance,” from opulentus “rich,” related to ops “wealth, resources”; it means great wealth or a lavish display of it.',C('opulence.s1','书面','Visitors noticed the opulence of the palace in its marble halls, gilded ceilings, and enormous chandeliers.','访客从大理石大厅、镀金天花板和巨型吊灯中感受到宫殿的奢华。','Visitors noticed the opulence of the palace / in its marble halls / gilded ceilings / and enormous chandeliers.','opulence 指大量财富或富丽奢华的展示。','昂贵材料和华丽装饰体现财富。'),M('The guide described the bare, unfurnished room as an example of opulence.','The guide described the marble halls and gilded ceilings as signs of the palace’s opulence.','空荡简陋的房间不体现财富与奢华。','distinction'),[Q(1,'What showed the palace’s opulence?','Marble halls and gilded ceilings.','Bare floors and empty rooms.','A simple paper schedule.','opulence.s1 指奢华富有。'),Q(1,'Which scene suggests opulence?','A mansion filled with costly art and lavish furnishings.','A tent with only a sleeping bag.','An empty room awaiting construction.','财富和昂贵陈设体现奢华。','meaning'),Q(1,'What noun is opulence related to?','opulent','oppress','optical','opulence and opulent are related forms.','word-formation'),Q(1,'Does opulence describe poverty?','No; it describes great wealth or lavish display.','Yes; it means having no possessions.','Yes; it means a political protest.','opulence 与财富充裕相关。','distinction')]);
P('opulent','From Latin opulentus “wealthy, rich,” related to opes “wealth”; it describes something rich and luxurious in appearance.',C('opulent.s1','生活','The hotel’s opulent lobby had a sweeping staircase, polished stone floors, and crystal lamps.','酒店富丽堂皇的大堂有宽阔的楼梯、抛光石地面和水晶灯。','The hotel’s opulent lobby / had a sweeping staircase / polished stone floors / and crystal lamps.','opulent 表示外观富丽、奢华的。','昂贵装潢使大堂显得奢华。'),M('The brochure called a plain room with bare concrete walls opulent.','The brochure called the richly furnished lobby opulent.','朴素空荡的房间不符合 opulent 的“奢华”含义。','distinction'),[Q(1,'Which features made the lobby opulent?','A grand staircase, stone floors, and crystal lamps.','Bare concrete walls and no furniture.','A small paper sign only.','opulent.s1 指富丽奢华的外观。'),Q(1,'Which adjective is closest to opulent?','luxurious','ordinary','oppressive','opulent means rich and luxurious in appearance.','meaning'),Q(1,'Which setting could be called opulent?','A palace dining room with gold trim and silk curtains.','An empty storage shed.','A bare concrete hallway.','华贵装潢符合 opulent。','context'),Q(1,'How does opulent relate to opulence?','Opulent is the adjective; opulence is the noun.','Both are plural nouns.','Opulence is the past tense of opulent.','opulent 是形容词，opulence 是名词。','word-formation')]);
P('or','From Old English oththe, related to other; it links alternatives, introduces a consequence if not, corrects a statement, and in “or so” means approximately.',[C('or.s1','通用','You can submit the report by email or bring a printed copy to the office.','你可以通过电子邮件提交报告，或者把打印件带到办公室。','You can submit the report by email / or bring a printed copy / to the office.','or.s1 用来连接两个或多个可能选项。','email 与 printed copy 是两种提交方式。'),C('or.s2','通用','Take the earlier bus, or you will arrive after the museum closes.','乘早一班公交吧，否则你会在博物馆关门后才到。','Take the earlier bus / or you will arrive / after the museum closes.','or.s2 可表示若不做前项就会发生后果。','后半句说明不赶早班车的结果。'),C('or.s3','通用','The meeting starts at noon—or rather, the guests should arrive by noon and the talk begins at twelve fifteen.','会议中午开始——确切地说，客人应在中午前到，演讲十二点十五分开始。','The meeting starts at noon—or rather / the guests should arrive by noon / and the talk begins at twelve fifteen.','or.s3 可用于纠正或进一步解释刚说的话。','or rather 引出更准确的说法。'),C('or.s4','口语','There were ten or so people waiting outside the small theater when the doors opened.','小剧院开门时，外面大约有十个人在等候。','There were ten or so people / waiting outside the small theater / when the doors opened.','or.s4 用在数字后面的 or so 中表示大约。','ten or so 是约十人。')],M('Take the earlier bus, or you will arrive before the museum opens, the notice said, although arriving early was the stated goal.','Take the earlier bus, or you may arrive after the museum closes.','警告后果应与“不乘早班车”相连，原句把结果方向颠倒了。','context'),[Q(1,'What are the two ways to submit the report?','Email it or bring a printed copy.','Mail a package or attend a concert.','Submit nothing under any condition.','or.s1 连接两种选择。'),Q(2,'What may happen if the traveler misses the earlier bus?','They may arrive after the museum closes.','They will definitely arrive before it opens.','The bus will become an orchestra.','or.s2 引出不采取行动的后果。'),Q(3,'What does “or rather” do in the meeting sentence?','Corrects or clarifies the earlier wording.','Offers an unrelated third meeting.','Means approximately twelve.','or.s3 用来修正刚才说法。','meaning'),Q(4,'How many people were waiting, approximately?','About ten.','Exactly ten thousand.','None.','ten or so means approximately ten.','number')]);
P('or else','From or + else; the phrase introduces what will happen if a warning or condition is ignored, and can sound threatening.',C('or else.s1','口语','Leave the emergency exit clear, or else rescue crews may not be able to reach the building quickly.','请保持紧急出口畅通，否则救援人员可能无法迅速到达楼内。','Leave the emergency exit clear / or else rescue crews may not be able / to reach the building quickly.','or else 表示否则，也常用于警告后果。','后半句是未清理出口可能造成的后果。'),M('The sign said “Block the exit, or else firefighters will reach everyone faster,” reversing the warning’s consequence.','The sign said “Keep the exit clear, or else firefighters may be delayed.”','堵住出口可能妨碍救援，不会让消防员更快到达。','context'),[Q(1,'What should people do with the emergency exit?','Keep it clear.','Block it with boxes.','Lock it permanently.','or else.s1 用来警告堵塞出口的后果。'),Q(1,'What could happen if the exit is blocked?','Rescue crews may be delayed.','The building becomes a library.','The exit grows wider.','or else introduces a negative consequence.','context'),Q(1,'Which sentence uses or else as a warning?','Wear your helmet, or else you could be injured.','Wear your helmet or else you might want to.','The helmet is or else blue.','短语引出不遵守要求可能的后果。','meaning'),Q(1,'What tone can or else carry?','A warning or threat.','A formal greeting.','A name for a musical instrument.','or else 常带警告语气。','register')]);
P('oracle','From Latin oraculum “divine announcement, place where an oracle is given,” from orare “speak”; it can mean an ancient shrine/priest giving prophecy, the prophecy itself, or a person treated as authoritative.',C('oracle.s1','宗教','Travelers brought questions to the oracle at Delphi, hoping the priestess would interpret the god’s response.','旅人带着问题来到德尔斐神谕所，希望女祭司能解释神的答复。','Travelers brought questions / to the oracle at Delphi / hoping the priestess / would interpret the god’s response.','oracle 可指古代回答未来问题的祭司或圣地，也指其神谕答复。','祭司或圣地传达被认为来自神明的答复。'),M('The guide called the written bus timetable an oracle because it was printed on paper.','The guide called the shrine that delivered prophetic answers an oracle.','oracle 是古代神谕机构或答复，不是普通时刻表。','word-choice'),[Q(1,'Where did the travelers take their questions?','To the oracle at Delphi.','To a bus station timetable.','To a modern optician’s shop.','oracle.s1 指古代神谕所或其祭司。'),Q(1,'What did the travelers hope to receive?','An interpretation of the god’s response.','A ticket to the next island.','A city ordinance.','神谕者解释神的答复。'),Q(1,'Which person might be called an oracle figuratively?','A respected expert whose judgments people trust.','A stranger whose advice no one follows.','A shopkeeper selling mirrors only.','oracle 也可比喻被视为权威的人。','meaning'),Q(1,'What does the Latin root orare mean?','Speak.','Choose.','Press.','orare means “speak.”','word-formation')]);
P('oral','From Latin os/oris “mouth” through oralis; oral describes spoken communication or the mouth, and as a noun it can mean an examination answered aloud.',[C('oral.s1','教育','The witness gave an oral account of the accident because the damaged phone had erased her written notes.','由于手机损坏导致书面笔记丢失，证人以口头方式陈述了事故经过。','The witness gave an oral account / of the accident / because the damaged phone / had erased her written notes.','oral.s1 表示口头的、用说话而非书写进行的。','证人用说话作陈述。'),C('oral.s2','医学','The dentist prescribed an oral rinse to be used after brushing, not swallowed as a drink.','牙医开了一种口腔漱洗液，要求刷牙后使用，而不是当饮料吞下。','The dentist prescribed an oral rinse / to be used after brushing / not swallowed as a drink.','oral.s2 表示与口腔有关或经口使用的。','漱洗液用于口腔。'),C('oral.s3','教育','Her final oral lasted twenty minutes, with the examiner asking follow-up questions after each answer.','她的期末口试持续了二十分钟，考官在每个回答后都会追问。','Her final oral lasted twenty minutes / with the examiner asking follow-up questions / after each answer.','oral.s3 作名词，指用口头回答的考试。','考生当场口头回答考官问题。')],M('The dentist told the patient to swallow the oral rinse as a meal replacement even though it was prescribed for the mouth.','The dentist told the patient to rinse the mouth with the oral solution and spit it out.','oral rinse 是口腔用漱洗液，不是代餐饮料。','usage'),[Q(1,'How did the witness give her account?','By speaking.','By sending an intact handwritten note.','By drawing a map only.','oral.s1 指口头陈述。'),Q(2,'Where is the oral rinse used?','In the mouth.','In the ear.','On a bicycle chain.','oral.s2 与口腔有关。'),Q(3,'How did the student answer in her final oral?','She spoke to the examiner.','She submitted only a written essay.','She sent a text after the exam.','oral.s3 是口头考试。'),Q(1,'Which phrase contrasts with an oral account?','a written account','an oral rinse','an oral exam','口头陈述与书面陈述相对。','distinction')]);
P('orange','From Old French orenge, via Arabic nāranj and Persian nārang, ultimately from a Dravidian source; the fruit name later gave the color its name.',[C('orange.s1','饮食','She peeled an orange for the train ride and packed the segments in a small reusable container.','她剥了一只橙子准备在火车上吃，并把果瓣装进可重复使用的小盒子。','She peeled an orange / for the train ride / and packed the segments / in a small reusable container.','orange.s1 作名词，指橙子等柑橘类水果。','她剥开水果并分成瓣。'),C('orange.s2','色彩','The artist mixed red and yellow until she found the exact orange needed for the sunset.','画家把红色和黄色混合，直到调出日落所需的准确橙色。','The artist mixed red and yellow / until she found / the exact orange / needed for the sunset.','orange.s2 作名词，指红黄之间的橙色。','调色得到一种颜色。'),C('orange.s3','色彩','A bright orange scarf made the gray winter coat easier to see from across the road.','亮橙色围巾让这件灰色冬衣从马路对面也更容易被看见。','A bright orange scarf / made the gray winter coat / easier to see / from across the road.','orange.s3 作形容词，表示橙色的。','orange 修饰 scarf，描述颜色。')],M('The painter said the fruit was an orange even though it was a blue wool scarf, not a citrus fruit.','The painter called the citrus fruit an orange and described the scarf as orange in color.','orange 作水果名词和颜色形容词需看所修饰的对象。','distinction'),[Q(1,'What did she pack for the train ride?','Segments of an orange.','A red-and-yellow paint mixture.','A gray winter coat.','orange.s1 指柑橘水果。'),Q(2,'How did the artist create the exact orange?','By mixing red and yellow.','By mixing blue and green.','By peeling the fruit.','orange.s2 是颜色名。'),Q(3,'What color was the scarf?','Bright orange.','Gray.','Colorless.','orange.s3 作形容词修饰 scarf。','meaning'),Q(1,'Which word gave the color name its origin?','The fruit name orange.','The word oral.','The word orchestra.','橙色名称源自水果名。','word-formation')]);
P('oration','From Latin oratio “speech, discourse,” from orare “speak”; an oration is a long, formal speech at a public or ceremonial event.',C('oration.s1','通用','The mayor delivered an oration at the memorial ceremony, honoring the volunteers who rebuilt the flood-damaged bridge.','市长在纪念仪式上发表正式演说，向重建洪水受损桥梁的志愿者致敬。','The mayor delivered an oration / at the memorial ceremony / honoring the volunteers / who rebuilt the flood-damaged bridge.','oration 指在公共或礼仪场合发表的长篇正式演说。','纪念仪式是正式演讲场合。'),M('The program called a two-word text message an oration delivered at the memorial ceremony.','The program called the mayor’s formal memorial address an oration.','oration 指较正式、较长的演说，不是简短短信。','register'),[Q(1,'Where did the mayor deliver the oration?','At a memorial ceremony.','In a private text message.','During a silent rehearsal.','oration.s1 是正式场合演说。'),Q(1,'Who was honored in the speech?','Volunteers who rebuilt the bridge.','The opticians who adjusted frames.','A group of orange trees.','例句说明志愿者是致敬对象。','context'),Q(1,'Which occasion suits an oration?','A public memorial service.','A quick private reminder.','A grocery list.','oration 常用于公共或礼仪场合。','register'),Q(1,'What does oration mean?','A formal public speech.','A person who gives eye exams.','A musical work sung without acting.','oration 指正式演说。','meaning')]);
P('orator','From Latin orator “speaker,” from orare “speak”; an orator is a skilled person who delivers formal public speeches.',C('orator.s1','语言','The young orator held the audience’s attention by stating her claim clearly and supporting it with precise examples.','年轻的演说家清楚陈述主张，并用准确例子支撑观点，吸引了听众。','The young orator held the audience’s attention / by stating her claim clearly / and supporting it / with precise examples.','orator 指善于在公开场合作正式演讲的人。','清晰陈述和有力举例展现演说技巧。','word-formation'),M('The reviewer called a speaker who could not address an audience an orator because she never spoke in public.','The reviewer called the skilled public speaker an orator.','orator 指正式公开演讲者，不能只因有人不会演讲而如此称呼。','distinction'),[Q(1,'What helped the orator hold the audience’s attention?','A clear claim supported by precise examples.','A long silence with no explanation.','A list of unrelated ticket prices.','orator.s1 指有演讲能力的人。'),Q(1,'Which person is an orator?','A skilled speaker addressing a public audience.','A listener who never speaks.','A person who tunes an orchestra instrument.','orator 是公开演讲者。','meaning'),Q(1,'What does orator derive from?','Latin orare, “speak.”','Greek optikos, “of sight.”','Latin optare, “choose.”','orator is related to Latin orare.','word-formation'),Q(1,'What did the reviewer evaluate?','The speaker’s public speaking ability.','Her skill at repairing lenses.','Her knowledge of fruit colors.','例句中的演说技巧吸引听众。','context')]);
P('oratorio','From Italian oratorio, from Latin oratorium “place of prayer”; the musical term names an extended concert work for singers and instruments, generally without acting or staging.',C('oratorio.s1','音乐','The choir performed an oratorio with orchestra and soloists, but no costumes or stage acting.','合唱团与管弦乐队、独唱者共同演出了清唱剧，但没有戏服或舞台表演。','The choir performed an oratorio / with orchestra and soloists / but no costumes / or stage acting.','oratorio 指大型声乐与器乐作品，通常演唱但不化装表演。','没有戏服和表演动作，符合清唱剧形式。','word-formation'),M('The theater advertised a fully staged musical with costumes and dialogue as an oratorio with no acting.','The theater advertised the unstaged choral work with orchestra as an oratorio.','oratorio 通常没有戏剧化表演；有舞台对白的戏剧不符此义。','distinction'),[Q(1,'What accompanied the choir in the oratorio?','An orchestra and soloists.','Only a silent film projector.','A group of actors in costume.','oratorio.s1 是声乐与乐队作品。'),Q(1,'What was absent from the performance?','Costumes and stage acting.','Singers.','Instrumental music.','清唱剧通常不化装演戏。'),Q(1,'Which work is an oratorio?','A large sacred or concert work sung without staging.','A short spoken news bulletin.','A fully acted comedy with costumes.','oratorio 是无舞台表演的大型声乐作品。','meaning'),Q(1,'Where does the term oratorio trace through?','Italian, from Latin for a place of prayer.','Old Norse for “odd number.”','Greek for “eye.”','oratorio comes through Italian from Latin oratorium.','word-formation')]);
P('oratory','From Latin oratoria “the art of public speaking,” from orator; it means the skill or practice of delivering formal speeches.',C('oratory.s1','文学','The debate coach studied classical oratory and taught students how to build a persuasive opening and conclusion.','辩论教练研究古典演讲术，并教学生如何构建有说服力的开头和结尾。','The debate coach studied classical oratory / and taught students / how to build a persuasive opening / and conclusion.','oratory 指发表正式演讲的技巧或艺术。','课程训练演讲结构与说服力。'),M('The handbook defined oratory as the ability to remain silent and avoid addressing an audience.','The handbook defined oratory as the skill of speaking persuasively to an audience.','oratory 是公开演讲的技巧，不是保持沉默。','meaning'),[Q(1,'What did the coach teach students to build?','A persuasive opening and conclusion.','An orchestra pit.','A mountain range.','oratory.s1 指演讲技巧。'),Q(1,'Which activity demonstrates oratory?','Delivering a structured persuasive speech.','Writing a shopping list without speaking.','Tuning a violin silently.','有结构地说服听众是演讲术。','meaning'),Q(1,'Which related word names a skilled public speaker?','orator','optician','organism','orator is the person; oratory is the skill.','word-formation'),Q(1,'Why study classical oratory?','To learn how to organize and deliver formal speeches.','To learn how to grow orchids.','To calculate the best lens angle.','教练研究演讲结构和表达方式。','context')]);
P('orbit','From Latin orbita “wheel track, course,” from orbis “circle”; it can mean a space path, a sphere of influence, or moving around a planet or star.',[C('orbit.s1','天文','The satellite completed one orbit around Earth every ninety minutes while sending weather data to the ground station.','这颗卫星每九十分钟绕地球运行一周，同时向地面站发送天气数据。','The satellite completed one orbit around Earth / every ninety minutes / while sending weather data / to the ground station.','orbit.s1 指物体在太空中绕行星或恒星反复运行的轨道。','卫星沿固定路径绕地球运行。'),C('orbit.s2','政治','The small kingdom fell within the empire’s orbit after it began relying on the empire for trade and defense.','这个小王国开始依赖帝国进行贸易和防务后，便落入帝国的势力范围。','The small kingdom fell within the empire’s orbit / after it began relying on the empire / for trade and defense.','orbit.s2 可比喻某人或国家周围的影响、活动范围。','经济和防务依赖带来政治影响。'),C('orbit.s3','天文','Several moons orbit the gas giant, each following a different path through space.','有几颗卫星绕这颗气态巨行星运行，各自沿不同轨道穿行于太空。','Several moons orbit the gas giant / each following a different path / through space.','orbit.s3 作动词，表示沿轨道绕行星或恒星运行。','moons 是运动主体，gas giant 是被环绕对象。')],M('The moon orbited around the gas giant while remaining fixed in one place and never moving.','The moon orbited the gas giant by moving along a curved path through space.','orbit 表示绕行运动，不能同时静止不动。','meaning'),[Q(1,'How long did the satellite take to complete an orbit?','Ninety minutes.','Ninety days.','One year.','orbit.s1 是绕地球运行的轨道周期。','number'),Q(2,'What did the kingdom’s orbit represent?','The empire’s sphere of influence.','A satellite path in space.','The kingdom’s circular border only.','orbit.s2 是影响范围的比喻义。'),Q(3,'What do the moons do around the gas giant?','They travel along paths around it.','They remain fixed and motionless.','They send weather reports to Earth.','orbit.s3 作动词表示绕行。'),Q(1,'Which use is literal astronomy?','The spacecraft entered orbit around Mars.','The country entered a rival’s orbit.','The debate fell outside the speaker’s orbit.','第一句指实际太空轨道。','distinction')]);
P('orbital','From orbit + -al; it describes a path or activity around a celestial body, and in anatomy it relates to the eye socket.',[C('orbital.s1','天文','The probe used a small orbital correction to remain on course around the planet.','探测器进行了一次小幅轨道修正，以继续沿行星轨道运行。','The probe used a small orbital correction / to remain on course / around the planet.','orbital.s1 指与行星、卫星或人造卫星轨道有关。','修正改变航天器沿行星运行的路径。'),C('orbital.s2','医学','The scan showed a fracture in the orbital bone around the patient’s left eye.','扫描显示患者左眼周围的眼眶骨有骨折。','The scan showed a fracture / in the orbital bone / around the patient’s left eye.','orbital.s2 指眼眶的、与眼球骨性容纳结构有关的。','骨折位置围绕眼球。')],M('The radiologist labeled the bone around the eye orbital even though the scan showed a wrist fracture.','The radiologist labeled the bone around the eye orbital because it forms part of the eye socket.','orbital 的解剖义指眼眶结构，不指手腕骨。','distinction'),[Q(1,'What did the probe correct?','Its path around the planet.','The patient’s eye socket.','A political alliance.','orbital.s1 指天体轨道相关。'),Q(2,'Where was the fracture?','In the bone around the left eye.','In the planet’s path through space.','In the patient’s wrist.','orbital.s2 指眼眶骨。'),Q(1,'Which phrase uses orbital in the space sense?','orbital mechanics','orbital cheekbone fracture','orbital eye socket','mechanics of spacecraft paths is the astronomical sense.','distinction'),Q(2,'Which body area is orbital?','The eye socket.','The knee joint.','The shoulder blade.','anatomical orbital relates to the eye socket.','meaning')]);
P('orbiter','From orbit + agent suffix -er; an orbiter is a spacecraft designed to travel around a planet rather than land on it.',C('orbiter.s1','科学','The orbiter mapped the planet from space for two years, while a separate lander studied the surface.','轨道飞行器在太空中对这颗行星测绘了两年，另一艘着陆器则研究其表面。','The orbiter mapped the planet from space / for two years / while a separate lander / studied the surface.','orbiter 指绕行星运行的航天器。','与着陆器不同，orbiter 留在行星轨道上。','word-formation'),M('Mission control called the spacecraft an orbiter even though it landed and remained on the planet’s surface.','Mission control called the spacecraft a lander after it touched down and stayed on the surface.','orbiter 绕行星运行；在表面着陆的是 lander。','distinction'),[Q(1,'Where did the orbiter map the planet from?','From space.','From a cave underground.','From the planet’s ocean floor.','orbiter.s1 指绕行星运行的航天器。'),Q(1,'What did the separate lander do?','Studied the planet’s surface.','Mapped the planet from orbit for two years.','Returned to Earth without landing.','例句区分轨道器和着陆器。','context'),Q(1,'Which craft is an orbiter?','A spacecraft circling a planet.','A probe resting on the surface.','A telescope fixed in a classroom.','orbiter 是绕行星飞行的航天器。','meaning'),Q(1,'How is orbiter formed?','orbit + -er','orbital + plural -s','orator + -ial','-er forms the noun for a craft that orbits.','word-formation')]);
P('orchard','From Old English ortgeard “fruit garden,” likely formed from wort “plant” + geard “yard”; it means land where fruit trees grow or a group of such trees.',[C('orchard.s1','通用','The family planted a new orchard on the sloping land and chose apple and pear trees that ripen at different times.','这家人在坡地上新建了果园，并选择成熟期不同的苹果树和梨树。','The family planted a new orchard / on the sloping land / and chose apple and pear trees / that ripen at different times.','orchard.s1 指种植果树的园地。','土地被规划用于种植果树。'),C('orchard.s2','通用','A small orchard of apricot trees stood behind the farmhouse, bright with blossoms in early spring.','农舍后面有一片小杏树林，早春时花开鲜艳。','A small orchard of apricot trees stood / behind the farmhouse / bright with blossoms / in early spring.','orchard.s2 可指成片生长的果树。','名词短语 orchard of apricot trees 指树群。')],M('The farmer called the empty paved parking lot an orchard although it had no fruit trees.','The farmer called the field planted with apple and pear trees an orchard.','orchard 指种植果树的园地或果树林，不是空停车场。','meaning'),[Q(1,'What did the family plant on the slope?','An orchard of apple and pear trees.','A parking lot.','A group of ocean probes.','orchard.s1 指果树种植园地。'),Q(2,'What was behind the farmhouse?','A small group of apricot trees.','A single empty shed.','A theater orchestra pit.','orchard.s2 可指果树林。'),Q(1,'Which land is an orchard?','A field planted with fruit trees.','A paved field with no plants.','A field of military equipment.','果园种植果树。','meaning'),Q(2,'What did the apricot trees look like in early spring?','They were covered with blossoms.','They had been removed.','They were bearing winter snow only.','例句说明杏树早春开花。','context')]);
P('orchestra','From Greek orkhestra, the circular space for dancing in front of a stage, through Latin and Italian; it means a large instrumental ensemble or the pit/seats in a theater.',[C('orchestra.s1','音乐','The orchestra rehearsed the symphony with strings, woodwinds, brass, and percussion under the conductor’s direction.','管弦乐队在指挥带领下，用弦乐、木管、铜管和打击乐排练交响曲。','The orchestra rehearsed the symphony / with strings, woodwinds, brass, and percussion / under the conductor’s direction.','orchestra.s1 指由多种乐器演奏者组成、由指挥带领的大型乐队。','不同声部共同演奏交响曲。'),C('orchestra.s2','戏剧','We chose seats in the orchestra, close to the musicians’ pit and near the front of the theater.','我们选了剧院正厅前排的座位，靠近乐师乐池。','We chose seats in the orchestra / close to the musicians’ pit / and near the front / of the theater.','orchestra.s2 可指乐池或紧挨乐池的剧院前排座位。','句子说的是剧场座区，不是乐队。')],M('The theater usher called the musicians’ pit an orchestra even though no players or seats were present there.','The theater usher called the area where musicians play the orchestra pit.','orchestra 的剧场义指乐师所在的区域或其附近座位，不能说那里完全没有乐师。','distinction'),[Q(1,'Which sections rehearsed the symphony?','Strings, winds, brass, and percussion.','Only the conductor’s office staff.','A group of orchard workers.','orchestra.s1 是多声部乐团。'),Q(2,'Where were the chosen seats?','Near the musicians’ pit at the theater front.','On a spacecraft in orbit.','Behind the stage in a storage room.','orchestra.s2 指乐池附近座位。'),Q(1,'Who led the ensemble rehearsal?','The conductor.','The theater usher.','The orchard owner.','大型管弦乐队由指挥带领。','context'),Q(2,'Which sentence uses orchestra to refer to theater seating?','They bought seats in the orchestra.','The orchestra rehearsed the symphony.','The conductor tuned the orchestra.','seats in the orchestra 是剧院座席义。','distinction')]);
P('orchestral','From orchestra + -al; it describes an orchestra or music written for an orchestra.',C('orchestral.s1','音乐','The film’s orchestral score grew louder as the rescue team reached the mountain pass.','救援队抵达山口时，电影的管弦乐配乐逐渐增强。','The film’s orchestral score grew louder / as the rescue team / reached the mountain pass.','orchestral 表示管弦乐队的或由管弦乐演奏的。','score 是由乐队演奏的配乐。','word-formation'),M('The composer called the solo flute recording orchestral even though no other instruments or ensemble were used.','The composer called the arrangement for strings, brass, and winds orchestral.','orchestral 关联管弦乐队或其音乐，单独长笛独奏不构成乐队编制。','distinction'),[Q(1,'What grew louder in the film?','The orchestral score.','The rescue team’s radio only.','The mountain wind forecast.','orchestral.s1 修饰管弦乐配乐。'),Q(1,'Which music is orchestral?','A symphonic arrangement for strings, winds, and brass.','A solo voice with no instruments.','A spoken announcement.','orchestral describes music for an orchestra.','meaning'),Q(1,'Which noun does orchestral modify in the example?','score','mountain','team','orchestral is the adjective describing the score.','grammar'),Q(1,'How is orchestral formed?','orchestra + -al','orchid + plural -s','orator + -ly','-al forms an adjective meaning related to orchestra.','word-formation')]);
P('orchestrate','From orchestra + -ate, originally “arrange music for an orchestra”; it also means to plan and coordinate actions to produce a particular result.',[C('orchestrate.s1','文化','The arranger orchestrated the folk melody for strings, brass, and a small group of woodwinds.','编曲者把这首民歌旋律改编为弦乐、铜管和小型木管乐队演奏的版本。','The arranger orchestrated the folk melody / for strings, brass, / and a small group of woodwinds.','orchestrate.s1 指为管弦乐队编曲。','编曲为多个乐器声部安排旋律。'),C('orchestrate.s1','通用','The relief director orchestrated deliveries from five towns so that medicine reached the valley before the storm.','救援负责人协调五个城镇的物资运送，使药品在风暴前送达山谷。','The relief director orchestrated deliveries / from five towns / so that medicine reached the valley / before the storm.','orchestrate.s1 也可指有计划地协调一系列行动。','负责人统筹多个地点的配送。')],M('The director orchestrated the deliveries by refusing to coordinate any town and sending every truck in the wrong direction.','The director orchestrated the deliveries by coordinating routes from all five towns.','统筹安排需要协调各方，而非拒绝协调并让车辆走错路。','meaning'),[Q(1,'What did the arranger do to the folk melody?','Arranged it for several orchestral sections.','Deleted every instrument part.','Turned it into a spoken weather report.','orchestrate.s1 可指为乐队编曲。'),Q(1,'Which action means orchestrating a piece of music?','Writing parts for strings, brass, and winds.','Changing the concert date only.','Selling tickets at the entrance.','为多个乐器声部编写安排是编曲。','context'),Q(1,'How did the relief director orchestrate the deliveries?','By coordinating routes from five towns.','By sending every truck the wrong way.','By stopping all medicine shipments.','orchestrate 也表示协调安排一系列行动。','meaning'),Q(1,'Which use is figurative rather than musical?','She orchestrated a citywide cleanup campaign.','He orchestrated the score for a symphony.','The orchestra tuned its violins.','协调活动是 orchestrate 的引申义。','distinction')]);
P('orchid','From Greek orchis “testicle,” referring to the shape of the plant’s paired tubers; an orchid is a flowering plant of the family Orchidaceae.',C('orchid.s1','生物','The greenhouse moved the orchid away from direct afternoon sun and kept its roots in a ventilated pot.','温室把兰花移离午后直射阳光，并将它的根养在通气的花盆里。','The greenhouse moved the orchid / away from direct afternoon sun / and kept its roots / in a ventilated pot.','orchid 指兰科开花植物。','花盆与遮阴环境用于栽培兰花。'),M('The gardener labeled a cactus with spines and no orchid flowers as an orchid.','The gardener labeled the flowering plant from the orchid family an orchid.','仙人掌不属于兰科，不能因也是盆栽就称作 orchid。','word-choice'),[Q(1,'Where did the greenhouse move the orchid?','Away from direct afternoon sun.','Into a sealed metal box.','Underwater in a fish tank.','orchid.s1 指兰科植物。'),Q(1,'What did the greenhouse do with the orchid’s roots?','Kept them in a ventilated pot.','Wrapped them in dry plastic permanently.','Removed them before watering.','例句说明兰花根部需要通气。','context'),Q(1,'Which plant is an orchid?','A flowering plant in Orchidaceae.','A thorny cactus from a different family.','A pine tree.','兰科植物才是 orchid。','meaning'),Q(1,'What did the Greek source word orchis refer to?','A testicle, based on the shape of paired tubers.','A flower’s orange color.','An orchestra pit.','orchid 的词源与块茎形状有关。','word-formation')]);
P('ordeal','From Old English ordēal, perhaps “judgment, decision,” later applied to a medieval trial in which innocence was judged through a physical test; today it usually means a painful, frightening, or exhausting experience.',[C('ordeal.s1','通用','The week-long power failure was an ordeal for the nursing home, whose staff had to keep medicines refrigerated with limited supplies.','持续一周的停电对这家养老院是场磨难，工作人员只能用有限物资为药品保冷。','The week-long power failure / was an ordeal for the nursing home / whose staff had to keep medicines refrigerated / with limited supplies.','ordeal.s1 指持续且痛苦、令人害怕或疲惫的经历。','停电持续多日并造成现实困难。'),C('ordeal.s2','历史','The museum exhibit explains that an accused person in a medieval ordeal might be tested by fire or water.','博物馆展览解释说，在中世纪神判中，被告可能要接受火或水的考验。','The museum exhibit explains / that an accused person in a medieval ordeal / might be tested / by fire or water.','ordeal.s2 指古代用火、水等身体考验判定有罪与否的神判。','展览介绍的是古代审判习俗。')],M('The nurse called a comfortable, trouble-free weekend an ordeal that had caused no stress or fatigue.','The nurse called the week-long power failure an ordeal because it created prolonged strain.','ordeal 表示严峻痛苦的经历，不是毫无困难的轻松周末。','distinction'),[Q(1,'Why was the power failure an ordeal for the nursing home?','It made it difficult to keep medicines cold.','It improved every service without effort.','It lasted only a few minutes and caused no change.','ordeal.s1 是持续造成困难的磨难。'),Q(2,'What might happen in the medieval ordeal described?','The accused could face a fire or water test.','The jury would compare modern DNA records.','The accused would take an ordinary oral exam.','ordeal.s2 是古代身体考验式审判。'),Q(1,'Which experience is an ordeal?','A long evacuation through dangerous weather.','A calm and effortless afternoon.','A routine five-minute walk in good weather.','ordeal 指严峻、令人疲惫的经历。','meaning'),Q(2,'What was the historical purpose of the ordeal?','To judge whether the accused was guilty.','To train a choir for a concert.','To calculate a spacecraft’s orbit.','神判曾被用来判断被告是否有罪。','context')]);
P('order','From Old French ordre and Latin ordo “row, rank”; senses include sequence, orderly state, authoritative command, giving an order, requesting goods/food, the goods requested, and the purpose phrase in order to.',[C('order.s1','通用','Please arrange the photographs in chronological order before the archivist scans them.','请先按时间顺序排列照片，再让档案员扫描。','Please arrange the photographs / in chronological order / before the archivist scans them.','order.s1 指事物前后排列的次序。','chronological order 按时间先后排列。'),C('order.s2','社会','The volunteers restored order in the crowded hall by opening a second exit and guiding people calmly.','志愿者打开第二个出口并冷静引导人群，使拥挤的大厅恢复秩序。','The volunteers restored order / in the crowded hall / by opening a second exit / and guiding people calmly.','order.s2 指规则得以遵守、局面安定有序的状态。','有序疏散恢复了安定秩序。'),C('order.s3','通用','The captain gave an order to keep the deck clear while the rescue boat was lowered.','救生艇放下时，船长下令保持甲板畅通。','The captain gave an order / to keep the deck clear / while the rescue boat was lowered.','order.s3 作名词，指有权威者要求服从的命令。','船长发出指令。'),C('order.s4','通用','The judge ordered the witness to answer the question directly.','法官命令证人直接回答问题。','The judge ordered the witness / to answer the question / directly.','order.s4 作动词，表示凭借权威命令某人做事。','法官对证人发出命令。'),C('order.s5','商业','We ordered two bowls of soup and a pot of tea at the harbor café.','我们在港口咖啡馆点了两碗汤和一壶茶。','We ordered two bowls of soup / and a pot of tea / at the harbor café.','order.s5 作动词，表示向商店或餐馆订购、点餐。','顾客要求餐馆提供食物和饮料。'),C('order.s6','商业','The bakery confirmed our order of twelve rolls before sending the driver out.','面包店在派司机出发前确认了我们订购的十二个面包卷。','The bakery confirmed our order / of twelve rolls / before sending the driver out.','order.s6 作名词，指已经订购的货物或所点菜品。','十二个面包卷是订单内容。'),C('order.s7','语法','She saved the receipt in order to claim a refund if the lens arrived damaged.','她保存收据，以便镜片到货时若有损坏可以申请退款。','She saved the receipt / in order to claim a refund / if the lens arrived damaged.','in order to + 动词原形表示目的。','保存收据的目的是必要时申请退款。')],M('The captain’s order said to keep the deck clear, but the crew filled it with boxes and called that obedience.','The crew obeyed the captain’s order by keeping the deck clear.','把甲板堆满箱子违反了保持畅通的命令。','distinction'),[Q(1,'In what order should the archivist scan the photographs?','Chronological order.','By the price of each frame.','By the size of the paper only.','order.s1 指排列顺序。'),Q(3,'What did the captain tell the crew to do?','Keep the deck clear.','Fill the deck with boxes.','Order soup from the café.','order.s3 是船长发出的命令。'),Q(5,'What did the customers order at the café?','Two bowls of soup and a pot of tea.','Twelve bakery rolls for delivery.','A new camera lens.','order.s5 作动词表示点餐。'),Q(7,'Why did she save the receipt?','To claim a refund if the lens arrived damaged.','To arrange photos chronologically.','To issue a command to the judge.','in order to introduces the purpose.','grammar')]);
P('orderly','From order + -ly; as an adjective it means arranged or conducted in a well-controlled way, and as a noun it is a hospital worker who assists patients and staff.',[C('orderly.s1','通用','The evacuation proceeded in an orderly way, with each classroom leaving after the teacher checked the corridor.','疏散有序进行，每间教室都在老师检查走廊后依次离开。','The evacuation proceeded in an orderly way / with each classroom leaving / after the teacher checked the corridor.','orderly.s1 作形容词，表示有条理、平静有序的。','班级按规则依次离开。'),C('orderly.s2','健康','A hospital orderly wheeled the patient to imaging while the nurse prepared the chart.','护士准备病历时，医院护工把患者推到影像检查室。','A hospital orderly wheeled the patient to imaging / while the nurse / prepared the chart.','orderly.s2 作名词，指在医院协助病人和工作人员的人员。','护工协助转运患者。')],M('The evacuation was orderly because everyone ran in different directions, blocked the corridor, and ignored instructions.','The evacuation was orderly because classrooms left one at a time after the corridor was checked.','混乱奔跑和堵塞通道不符合 orderly 的“有序”义。','distinction'),[Q(1,'How did the classrooms leave?','One at a time after the corridor was checked.','All at once through a blocked corridor.','Without any teacher present.','orderly.s1 表示有序进行。'),Q(2,'What did the hospital orderly do?','Wheeled the patient to imaging.','Interpreted the scan as a physician.','Issued a city ordinance.','orderly.s2 是医院护工。'),Q(1,'Which is an orderly process?','A queue moves forward calmly in turn.','People push in every direction.','Workers ignore the posted plan.','有条不紊、按序进行体现 orderly。','meaning'),Q(2,'Which setting most commonly employs an orderly?','A hospital.','An orchard only.','A planet’s orbit.','orderly 作名词可指医院工作人员。','context')]);
P('ordinal','From Latin ordinalis “showing order or rank,” from ordo “order”; it describes position in a sequence and, as a noun, is a number such as first or third.',[C('ordinal.s1','数学','The ordinal labels on the race results showed who finished first, second, and third.','比赛结果上的序数标明谁获得第一、第二和第三名。','The ordinal labels on the race results / showed who finished / first, second, and third.','ordinal.s1 作形容词，表示顺序的而非数量的。','名次标记位置次序。'),C('ordinal.s2','语言','“Third” is an ordinal because it tells a reader a position rather than how many objects there are.','third 是序数，因为它告诉读者一个位置，而不是物品有多少个。','“Third” is an ordinal / because it tells a reader a position / rather than how many objects there are.','ordinal.s2 作名词，指 first、third 等表示位置的数。','third 表示序列位置。')],M('The results used ordinal numbers to state that the runner completed exactly three laps, not which position she held.','The results used a cardinal number to state she completed three laps and an ordinal to state she finished third.','third 表示名次；three 表示数量，不能混为一类。','distinction'),[Q(1,'What did the ordinal labels show in the race results?','Finishing positions.','The total number of spectators.','The length of each lane.','ordinal.s1 表示顺序位置。'),Q(2,'Why is “third” an ordinal?','It states a position in a sequence.','It counts three objects.','It names a fraction of a circle.','ordinal.s2 指序数。'),Q(1,'Which word is an ordinal adjective?','fourth','four','fourfold','fourth marks order; four marks quantity.','distinction'),Q(2,'Which statement uses an ordinal?','She finished second.','She bought two tickets.','Two runners were absent.','second states position in a race.','grammar')]);
P('ordinance','From Old French ordenance, from Medieval Latin ordinantia, related to order; an ordinance is an authoritative rule or law, often made by a municipality.',C('ordinance.s1','法律','The city passed an ordinance limiting construction noise after nine in the evening.','市政府通过了一项条例，限制晚上九点后的施工噪声。','The city passed an ordinance / limiting construction noise / after nine in the evening.','ordinance 指当局发布的命令或地方法规。','市政府有权通过地方条例。'),M('The clerk filed the city’s construction-noise law under ordnance because both words concern rules and equipment.','The clerk filed the city’s construction-noise law as an ordinance.','ordinance 是法律条例；ordnance 指军械，二者拼写相近但意义不同。','confusable'),[Q(1,'What did the city ordinance limit?','Construction noise after nine p.m.','Military shells in a museum.','The order of a concert program.','ordinance.s1 是地方条例。'),Q(1,'Who passed the ordinance?','The city.','The orchestra.','A single tourist.','地方政府可通过条例。','context'),Q(1,'Which spelling means a local law?','ordinance','ordnance','ordnancee','ordinance refers to an authoritative rule or law.','spelling'),Q(1,'Which pair is correctly matched?','ordinance—law; ordnance—military equipment','ordinance—cannon; ordnance—city law','both words—an orchestra','ordinance and ordnance are confusable but distinct.','confusable')]);
P('ordinarily','From ordinary + -ly; it means under usual conditions or in the normal way.',C('ordinarily.s1','通用','The footbridge is ordinarily open at sunrise, but crews closed it today to replace a damaged railing.','这座人行桥通常在日出时开放，但今天施工队为更换损坏的栏杆将其关闭。','The footbridge is ordinarily open at sunrise / but crews closed it today / to replace a damaged railing.','ordinarily 表示通常情况下、按常态而言。','today 的临时关闭与平常开放形成对照。','word-formation'),M('The notice said the bridge was ordinarily closed every morning but open only on one unusual day each year.','The notice said the bridge was ordinarily open each morning but closed today for repairs.','ordinarily 表示通常状态，不能把罕见例外说成常态。','meaning'),[Q(1,'When is the footbridge ordinarily open?','At sunrise.','Only once every decade.','Only during the night.','ordinarily.s1 指通常情况。'),Q(1,'Why was it closed today?','Crews were replacing a damaged railing.','It is ordinarily closed at sunrise.','The bridge had become an orchestra.','例句说明今天关闭是为了维修。','context'),Q(1,'Which word is closest to ordinarily?','normally','rarely','accidentally','ordinarily means under usual circumstances.','meaning'),Q(1,'How is ordinarily formed?','ordinary + -ly','order + plural -s','ordain + past -ed','-ly forms the adverb ordinarily.','word-formation')]);
P('ordinary','From Latin ordinarius “regular, usual,” from ordo “order”; it can mean usual and unsurprising, or merely average in quality.',[C('ordinary.s1','通用','The ordinary Tuesday market looked different after the street musicians and flower stalls arrived.','街头乐手和花摊出现后，这个平常的周二集市看起来不一样了。','The ordinary Tuesday market / looked different / after the street musicians and flower stalls arrived.','ordinary.s1 指普通、常见、没有稀奇之处的。','“普通周二集市”与后来出现的特殊景象对比。'),C('ordinary.s2','评价','The reviewer found the novel ordinary: its plot was understandable but offered no fresh ideas or memorable scenes.','评论者认为这本小说平庸：情节容易理解，却没有新鲜想法或难忘场面。','The reviewer found the novel ordinary / its plot was understandable / but offered no fresh ideas / or memorable scenes.','ordinary.s2 可表示质量或水平只属平均、不出色。','评价明确指出作品缺少新意。')],M('The reviewer called the novel ordinary because it was unusually brilliant and unlike anything previously written.','The reviewer called the novel original and exceptional because it was unusually brilliant.','特别出色、独创的作品不是平庸普通的。','distinction'),[Q(1,'What made the market look different?','Musicians and flower stalls arrived.','It remained completely unchanged.','The novel won a literary prize.','ordinary.s1 表示常态、普通。'),Q(2,'Why did the reviewer call the novel ordinary?','It lacked fresh ideas and memorable scenes.','It was the most original book ever written.','It was too difficult for anyone to read.','ordinary.s2 表示质量平庸。'),Q(1,'Which event is ordinary?','A routine weekday bus ride.','A once-in-a-century solar event.','A record-breaking discovery.','ordinary.s1 means usual and unsurprising.','meaning'),Q(2,'Which comment uses ordinary as criticism?','The meal was average and not especially memorable.','The meal was a familiar everyday dish.','The restaurant opened at its regular time.','此处 ordinary 评价质量一般。','distinction')]);
P('ordinary people','A phrase built from ordinary + people; it contrasts the general public with people who are wealthy, powerful, famous, or specially privileged.',C('ordinary people.s1','通用','The radio program asked ordinary people how rising rent had changed their daily routines.','广播节目询问普通民众，房租上涨如何改变了他们的日常生活。','The radio program asked ordinary people / how rising rent / had changed their daily routines.','ordinary people 指没有特殊身份或特权的一般民众。','节目关注日常生活而非权贵或名人。'),M('The report used ordinary people to mean only ministers and billionaires who held special public power.','The report used ordinary people to mean members of the general public without special privilege.','普通人通常与拥有特殊权力或特权的人相对。','distinction'),[Q(1,'Who did the radio program interview?','Members of the general public.','Only ministers and billionaires.','The hosts of an orchestra.','ordinary people.s1 指普通民众。'),Q(1,'What issue did they discuss?','How rising rent changed daily routines.','How to choose an orbital correction.','How to grow an orchid.','例句强调普通人的租房经历。','context'),Q(1,'Which group best fits ordinary people?','Residents with varied everyday jobs and no special public status.','Only celebrities with exceptional privileges.','Only elected heads of government.','短语指一般民众。','meaning'),Q(1,'Why is ordinary people plural?','It refers to a group of people.','Ordinary always takes a singular verb.','People is the plural form of person.','people 指多人群体。','grammar')]);
P('ordinate','From Latin ordinata, feminine past participle of ordinare “arrange”; in Cartesian geometry the ordinate is the y-coordinate, measured parallel to the y-axis.',C('ordinate.s1','数学','For the point (4, 7), the ordinate is 7, the second coordinate measured along the y-axis.','点(4, 7)的纵坐标是7，也就是沿y轴测得的第二个坐标。','For the point (4, 7) / the ordinate is 7 / the second coordinate / measured along the y-axis.','ordinate 指笛卡尔平面坐标中的纵坐标，即y坐标。','坐标对中第二个数对应纵轴方向。'),M('For the point (4, 7), the worksheet identified 4 as the ordinate and 7 as the abscissa.','For the point (4, 7), the worksheet identified 7 as the ordinate and 4 as the abscissa.','纵坐标是第二个数7，横坐标是第一个数4。','distinction'),[Q(1,'What is the ordinate of point (4, 7)?','7','4','11','ordinate.s1 is the second coordinate.','number'),Q(1,'Along which axis is the ordinate measured?','The y-axis.','The x-axis.','The z-axis in every two-dimensional graph.','ordinate is the y-coordinate.','meaning'),Q(1,'Which coordinate is the ordinate in (x, y)?','y','x','the sum x+y','The ordinate is the y-coordinate.','word-choice'),Q(1,'What is the first coordinate commonly called?','The abscissa.','The ordinate.','The ordinal.','x is the abscissa; y is the ordinate.','distinction')]);
P('ordnance','From a clipped form of ordinance, historically associated with military provisions and equipment; today ordnance means cannons, shells, weapons, and other military stores.',C('ordnance.s1','军事','The museum catalog listed the cannon and ammunition as ordnance recovered from the coastal fort.','博物馆目录把从海岸堡垒回收的大炮和弹药列为军械。','The museum catalog listed the cannon and ammunition / as ordnance / recovered from the coastal fort.','ordnance 指大炮、炮弹及其他军事装备或军需品。','大炮和弹药均属于军械。'),M('The city clerk filed the new parking ordinance under ordnance because the two spellings look similar.','The city clerk filed the parking law under ordinance and the cannon inventory under ordnance.','ordnance 指军械；地方法规是 ordinance。','confusable'),[Q(1,'What did the museum list as ordnance?','A cannon and ammunition.','A municipal noise law.','An orchestra’s sheet music.','ordnance.s1 指军事装备。'),Q(1,'Which word means “military weapons and supplies”?','ordnance','ordinance','ordinate','ordnance is the military-equipment word.','confusable'),Q(1,'Which spelling refers to a city law?','ordinance','ordnance','ordnancee','ordinance means an authoritative rule or law.','spelling'),Q(1,'What is the difference between ordinance and ordnance?','A law versus military equipment.','A y-coordinate versus an x-coordinate.','A fruit versus a color.','两词拼写相近但义项不同。','distinction')]);
P('ore','From Old English ōra, likely borrowed from a Germanic source meaning unworked metal; it means rock or soil rich enough in metal to mine and the raw material sent for extraction.',[C('ore.s1','地质','The geologists found copper ore in the ridge, where mineral veins had formed in fractured rock.','地质学家在山脊发现铜矿石，矿脉形成于破裂岩层中。','The geologists found copper ore / in the ridge / where mineral veins / had formed in fractured rock.','ore.s1 指含有足量金属、值得开采的岩石或土壤。','铜矿石含有可开采的铜。'),C('ore.s2','工业','The mine sent the crushed ore to a processing plant, where workers separated the metal from the surrounding rock.','矿山把碎矿石送到加工厂，工人在那里将金属与周围岩石分离。','The mine sent the crushed ore / to a processing plant / where workers separated the metal / from the surrounding rock.','ore.s2 指送去加工以提取金属的矿石原料。','碎矿石作为冶炼厂的原料。')],M('The geologist called clean quartz with no recoverable metal copper ore.','The geologist called rock containing mineable copper copper ore.','若不含值得提取的铜，就不能称为铜矿石。','distinction'),[Q(1,'What did the geologists find in the ridge?','Copper ore.','A finished copper wire.','An empty orchard.','ore.s1 指含金属、可开采的岩石。'),Q(2,'Where did the mine send the crushed ore?','To a processing plant.','To a theater orchestra pit.','To the city council.','ore.s2 是送去提取金属的原料。'),Q(1,'Which rock qualifies as ore?','Rock containing enough valuable metal to mine.','Any rock with no useful mineral.','A polished metal tool.','ore requires enough recoverable metal to be worth mining.','meaning'),Q(2,'What happens to ore at the processing plant?','Metal is separated from surrounding rock.','It becomes a city ordinance.','It is planted as a fruit tree.','加工厂从矿石中提取金属。','context')]);
P('organ','From Latin organum, from Greek organon “instrument, tool”; it can mean a body/plant part with a function, a pipe keyboard instrument, or a publication/agency representing a group.',[C('organ.s1','医学','The liver is an organ that processes nutrients and helps remove waste from the blood.','肝脏是一种器官，负责处理营养物并帮助清除血液中的废物。','The liver is an organ / that processes nutrients / and helps remove waste / from the blood.','organ.s1 指承担特定功能的身体或植物部分。','肝脏承担身体功能。'),C('organ.s2','音乐','She practiced the organ in the church, using both the keyboard and the foot pedals.','她在教堂练习管风琴，同时使用键盘和脚踏板。','She practiced the organ / in the church / using both the keyboard / and the foot pedals.','organ.s2 指通过音管送风发声的大型键盘乐器。','键盘与脚踏板是管风琴的演奏部件。'),C('organ.s3','传媒','The association’s monthly bulletin served as its official organ, announcing policy decisions to members.','该协会的月刊充当其机关刊物，向会员发布政策决定。','The association’s monthly bulletin / served as its official organ / announcing policy decisions / to members.','organ.s3 可指代表团体或政府发声的报刊、机构或宣传工具。','刊物代表协会向会员传达立场。')],M('The church’s organ processed nutrients from the blood while the liver played notes on its pedals.','The liver processed nutrients, while the church organ produced music from its keyboard and pipes.','器官和乐器是 organ 的不同义项，不能把肝脏与管风琴功能混淆。','confusable'),[Q(1,'What does the liver do as an organ?','Processes nutrients and helps remove waste.','Plays music through foot pedals.','Publishes policy announcements.','organ.s1 指身体器官。'),Q(2,'How did she play the organ?','With the keyboard and foot pedals.','By processing blood nutrients.','By printing an association bulletin.','organ.s2 指管风琴。'),Q(3,'What was the association’s official organ?','Its monthly bulletin.','Its liver.','Its church instrument.','organ.s3 指代表团体发声的刊物。'),Q(1,'Which is a body organ?','The liver.','The church keyboard instrument.','A group’s official bulletin.','肝脏是身体器官。','distinction')]);
P('organic','From French organique and Latin organicus, ultimately from Greek organikos “instrumental”; senses include living things, carbon chemistry, pesticide-free production, and naturally connected development.',[C('organic.s1','生物','The compost contained organic matter from leaves and food scraps that soil organisms were breaking down.','堆肥含有由土壤生物分解的树叶和厨余有机物。','The compost contained organic matter / from leaves and food scraps / that soil organisms / were breaking down.','organic.s1 指来自或涉及活的动植物。','树叶和食物残渣来自生物。'),C('organic.s2','化学','Methane is an organic compound because its molecules contain carbon bonded to hydrogen.','甲烷是一种有机化合物，因为它的分子含有碳与氢的键合。','Methane is an organic compound / because its molecules contain / carbon bonded to hydrogen.','organic.s2 指有机化学的，常涉及含碳化合物。','甲烷分子有碳氢结构。'),C('organic.s3','农业','The farm used organic methods and avoided synthetic pesticides while rotating crops to protect the soil.','农场采用有机种植方法，避免使用合成杀虫剂，并轮作以保护土壤。','The farm used organic methods / and avoided synthetic pesticides / while rotating crops / to protect the soil.','organic.s3 指不用人工合成化肥或杀虫剂种植、生产的。','生产方式避免合成杀虫剂。'),C('organic.s4','书面','The committee’s organic growth came from local volunteers gradually taking on roles rather than from a top-down redesign.','委员会是由当地志愿者逐步承担职责而自然发展起来的，并非自上而下重新设计。','The committee’s organic growth came from local volunteers / gradually taking on roles / rather than from a top-down redesign.','organic.s4 可指作为相互关联整体自然发展的，而非人为拼凑。','组织结构由成员逐渐发展形成。')],M('The farm called its chemically treated crops organic even though it regularly sprayed synthetic pesticides.','The farm called its crops organic because it avoided synthetic pesticides and used soil-friendly methods.','有机种植不应与使用合成杀虫剂的方式混为一谈。','distinction'),[Q(1,'What made the compost organic matter?','It came from leaves and food scraps.','It was made from metal and glass.','It contained only synthetic plastic.','organic.s1 relates to living plants and animals.','meaning'),Q(2,'Why is methane an organic compound here?','Its molecules contain carbon bonded to hydrogen.','It contains no carbon.','It is grown without pesticides.','organic.s2 refers to carbon chemistry.','word-choice'),Q(3,'Which method did the farm avoid?','Using synthetic pesticides.','Rotating crops.','Protecting the soil.','organic.s3 concerns production without synthetic pesticides.','context'),Q(4,'How did the committee grow organically?','Volunteers gradually took on roles.','Leaders imposed a complete redesign overnight.','Members were randomly assigned unrelated duties.','organic.s4 means developing naturally as a connected whole.','distinction')]);
P('organically','From organic + -ally; it means by using biological processes or through gradual, natural development rather than force.',C('organically.s1','通用','The neighborhood group grew organically as more residents volunteered after seeing the first garden succeed.','第一个社区花园成功后，越来越多居民自愿加入，这个邻里团体便自然壮大。','The neighborhood group grew organically / as more residents volunteered / after seeing the first garden succeed.','organically 可表示通过生物过程，也可表示自然、渐进地发展。','居民自发加入，团体逐步扩大。','word-formation'),M('The neighborhood group grew organically because officials assigned every resident a fixed role before anyone volunteered.','The neighborhood group grew organically as residents joined voluntarily over time.','由上级强制指定并非自发、渐进的发展。','distinction'),[Q(1,'What led more residents to join the group?','The first garden’s success.','A mandatory assignment from officials.','A new ordinance about optics.','organically.s1 描述自然发展。'),Q(1,'How did the neighborhood group grow?','Gradually, through voluntary participation.','Instantly through forced assignments.','It did not grow at all.','organically means in a natural, unforced way.','meaning'),Q(1,'Which phrase is closest to grew organically?','developed gradually on its own','was assembled by force overnight','was canceled before it began','organically can describe natural development.','distinction'),Q(1,'What word is organically formed from?','organic','organ','ordinary','-ally forms an adverb from organic.','word-formation')]);
P('organisation','British spelling of organization, from French organisation and Latin organizare; it can mean a structured group or the way parts are planned and arranged.',[C('organisation.s1','通用','The conservation organisation hired volunteers to restore wetlands used by migrating birds.','这个自然保护组织招募志愿者修复候鸟使用的湿地。','The conservation organisation / hired volunteers / to restore wetlands / used by migrating birds.','organisation.s1 指为共同目标组成的团体或机构。','该机构组织志愿者开展保护工作。'),C('organisation.s2','通用','The clear organisation of the workshop schedule gave each speaker enough time for questions.','研讨会日程安排清晰，保证每位演讲者都有充足的提问时间。','The clear organisation of the workshop schedule / gave each speaker / enough time / for questions.','organisation.s2 指系统各部分被计划和安排的方式。','时间安排让每位演讲者都获得问答时段。')],M('The organisation had no members or shared purpose, yet the report called it a structured group.','The organisation was a structured group of volunteers with a shared conservation goal.','organisation 作机构义要求有一定结构的团体，不是无成员的空名。','meaning'),[Q(1,'What did the conservation organisation do?','Hired volunteers to restore wetlands.','Sold theater tickets.','Measured an eye’s orbital bone.','organisation.s1 指共同目标的机构。'),Q(2,'What did clear organisation of the schedule provide?','Enough time for each speaker’s questions.','A new conservation group.','A different spelling of ordinary.','organisation.s2 指安排方式。'),Q(1,'Which spelling is standard in British English?','organisation','organizatione','organisasion','organisation is the British spelling.','spelling'),Q(2,'Which sense concerns the arrangement of parts?','The organisation of the workshop schedule.','The conservation organisation itself.','The group’s volunteers as people.','s2 refers to how parts are planned and arranged.','distinction')]);
P('organism','From French organisme and Greek organon “instrument”; it means a living thing or, figuratively, an interdependent system whose parts work together like a body.',[C('organism.s1','生物','A single-celled organism can survive in the pond even though it is invisible without a microscope.','一种单细胞生物即使肉眼看不见，也能在池塘中生存。','A single-celled organism can survive / in the pond / even though it is invisible / without a microscope.','organism.s1 指动物、植物、细菌等任何生物。','单细胞生物是微小生命体。'),C('organism.s2','比喻','The editor described the newsroom as an organism whose reporters, designers, and fact-checkers depended on one another.','编辑把新闻编辑部比作一个有机体系，记者、设计师和核查员彼此依赖。','The editor described the newsroom as an organism / whose reporters, designers, and fact-checkers / depended on one another.','organism.s2 可比喻各部分互相依存的系统。','编辑部各岗位像生命体器官般协作。')],M('The biologist called a plastic bottle a living organism even though it could not grow, reproduce, or carry out life processes.','The biologist called the single-celled pond life an organism.','无生命塑料瓶不是生物体。','distinction'),[Q(1,'Why was the pond organism difficult to see?','It was single-celled and needed a microscope.','It was a large mammal.','It was a newsroom department.','organism.s1 指生命体。'),Q(2,'What made the newsroom like an organism?','Its staff roles depended on one another.','It had no people working in it.','It reproduced like a bacterium.','organism.s2 是互相依存系统的比喻。'),Q(1,'Which is an organism?','A bacterium.','A plastic bottle.','A stone.','organism.s1 means a living thing.','meaning'),Q(2,'Which system could figuratively be an organism?','A hospital team whose units rely on one another.','A pile of unrelated objects.','An empty desk.','互相依存的组织可比喻为 organism。','distinction')]);
P('organisms','Plural of organism; it refers to living things such as plants, animals, and microorganisms.',C('organisms.s1','科学','Researchers counted microorganisms and larger organisms in each water sample to compare the health of the two ponds.','研究人员统计每份水样中的微生物和较大的生物，以比较两个池塘的健康状况。','Researchers counted microorganisms and larger organisms / in each water sample / to compare the health / of the two ponds.','organisms 是 organism 的复数，指多种生物体。','水样中统计了大小不同的生命体。','plural'),M('The report used organisms for a single organism and stated that the word was singular.','The report used organism for one living thing and organisms for several.','organisms 是复数形式，单数是 organism。','plural'),[Q(1,'What did the researchers count?','Microorganisms and larger living things.','Only plastic fragments.','The number of bridges.','organisms.s1 指生物体。'),Q(1,'Why did they compare the water samples?','To assess the health of the ponds.','To arrange an orchestra.','To check a city ordinance.','例句说明统计生物以比较池塘健康。','context'),Q(1,'What is the singular of organisms?','organism','organism’s','organist','organisms is the plural of organism.','plural'),Q(1,'Which phrase is grammatically correct?','Many organisms live in the pond.','Many organism lives in the pond.','One organisms live in the pond.','复数 many 后用 organisms。','grammar')]);
P('organization','From organize + -ation, ultimately from Greek organon “tool, instrument”; it means a group working for a purpose or the act of arranging parts into a system.',C('organization.s1','社会','The organization trains volunteers to deliver meals, and its careful organization keeps each route on schedule.','这个组织培训志愿者送餐，而细致的组织安排让每条路线都按时进行。','The organization trains volunteers to deliver meals / and its careful organization / keeps each route / on schedule.','organization.s1 可指共同做事的团体，也可指组织、安排的行为。','句中前一个organization指机构，后一个指安排工作的方法。'),M('The organization had no members or shared purpose, but the report described it as a group working together.','The organization brought volunteers together around the shared goal of delivering meals.','没有成员和共同目标就不能称为共同工作的组织。','meaning'),[Q(1,'What does the organization train volunteers to do?','Deliver meals.','Inspect orbital bones.','Rehearse an oratorio.','organization.s1 指共同目标的团体。'),Q(1,'What does “careful organization” help keep on schedule?','Each delivery route.','The orchestra’s musical key.','The city’s ordinary market.','这里 organization 指安排方式。'),Q(1,'Which group is an organization?','A charity with members working toward a shared goal.','A random crowd with no shared purpose.','One unlabeled tool.','organization 指有共同目标的团体。','meaning'),Q(1,'How is organization formed?','organize + -ation','organ + plural -s','ordinary + -ly','-ation forms the noun organization from organize.','word-formation')]);
P('organizational','From organization + -al; it means concerning an institution’s structure, management, or operation.',C('organizational.s1','商业','The consultant recommended an organizational change that clarified who approved budgets across the regional offices.','顾问建议进行组织架构调整，明确各地区办公室由谁审批预算。','The consultant recommended an organizational change / that clarified / who approved budgets / across the regional offices.','organizational 表示与机构结构、管理或运作方式有关。','调整明确了审批职责。','word-formation'),M('The report called a new office paint color an organizational change even though roles, structure, and operations stayed the same.','The report called a change in budget-approval responsibilities an organizational change.','只改墙面颜色不涉及组织结构或管理。','distinction'),[Q(1,'What did the consultant’s organizational change clarify?','Who approved budgets.','Which paint color to use.','How many orchids to water.','organizational.s1 关乎机构管理职责。'),Q(1,'Which phrase naturally uses organizational?','organizational structure','organizational orange','organizational rainfall','organizational relates to structure or management.','collocation'),Q(1,'What does organizational describe?','Something concerning how an institution is arranged or managed.','A living organism only.','A person who gives a speech.','该形容词指机构结构或运作方面。','meaning'),Q(1,'How is organizational formed?','organization + -al','organize + past -ed','organ + comparative -er','-al forms an adjective from organization.','word-formation')]);
P('organize','From French organiser, from organ; it means to plan an event, arrange things into a system, or bring people together into a structured group such as a union.',[C('organize.s1','通用','Mina organized the field trip by booking the bus, confirming the museum visit, and sending families a schedule.','米娜通过订大巴、确认参观安排并向家长发送日程，筹备了这次实地考察。','Mina organized the field trip / by booking the bus / confirming the museum visit / and sending families a schedule.','organize.s1 指策划并安排活动或工作。','多项准备工作组成活动筹备。'),C('organize.s2','通用','He organized the repair tools by size and labeled each drawer so the crew could find them quickly.','他按尺寸整理维修工具，并给每个抽屉贴上标签，方便团队快速查找。','He organized the repair tools / by size / and labeled each drawer / so the crew could find them quickly.','organize.s2 指把物品整理成清晰系统。','分类和标签让物品容易找到。'),C('organize.s3','社会','The warehouse workers organized a union to negotiate safer shifts and clearer overtime rules.','仓库工人组织成立了工会，以协商更安全的轮班和更明确的加班规定。','The warehouse workers organized a union / to negotiate safer shifts / and clearer overtime rules.','organize.s3 指把人们联合起来组成工会或有结构的团体。','工人组成工会共同协商。')],M('Mina organized the field trip by forgetting to book transport, notify families, and confirm the museum visit.','Mina organized the field trip by booking transport, notifying families, and confirming the visit.','筹备活动意味着安排必要事项；故意遗漏所有准备与此相反。','distinction'),[Q(1,'How did Mina organize the field trip?','She booked the bus, confirmed the visit, and sent a schedule.','She canceled the museum and told no one.','She sorted tools into drawers.','organize.s1 是筹备活动。'),Q(2,'How did he organize the repair tools?','By size, with labeled drawers.','By forming a labor union.','By booking a bus.','organize.s2 是整理物品。'),Q(3,'Why did the workers organize a union?','To negotiate safer shifts and overtime rules.','To arrange the field trip.','To sort tools by size.','organize.s3 指组建工会。'),Q(1,'Which task involves organizing an event?','Reserving a venue and setting a schedule.','Labeling tools in a drawer.','Forming a union to negotiate.','预订场地并排定时间是活动筹备。','distinction')]);
P('organizer','From organize + -er; the suffix names a person or thing that performs an organizing role.',C('organizer.s1','通用','The conference organizer sent speakers a final schedule and assigned each session a room.','会议组织者向演讲者发送了最终日程，并为每场活动安排了房间。','The conference organizer / sent speakers a final schedule / and assigned each session / a room.','organizer.s1 指筹划并安排活动的人。','此人负责日程和场地。','word-formation'),M('The conference organizer sent no schedule, arranged no rooms, and had no role in planning the event.','The conference organizer planned the schedule and arranged rooms for the event.','筹办活动并安排事务才体现 organizer 的职责。','meaning'),[Q(1,'What did the conference organizer assign?','A room for each session.','A new mountain range.','A style of Asian pottery.','organizer.s1 is the person arranging the conference.'),Q(1,'Which task best fits an organizer?','Coordinating a conference schedule and rooms.','Attending without helping plan.','Studying bird migration in the field.','An organizer plans and coordinates an event.','meaning'),Q(1,'Who is the organizer in the example?','The person who sent the schedule and assigned rooms.','A speaker who received the schedule.','A visitor who entered the wrong room.','The role is identified by the planning actions.'),Q(1,'What does the suffix -er contribute in organizer?','It names a person who organizes.','It marks a past-tense verb.','It means “without organization.”','-er commonly forms an agent noun from organize.','word-formation')]);
P('orient','From French orienter, from orient “east”; it means to position something or help someone become familiar with a place or situation.',[C('orient.s1','教育','The first-day guide helped new students orient themselves to the library, labs, and campus routes.','第一天的向导帮助新生熟悉图书馆、实验室和校园路线。','The first-day guide helped new students / orient themselves / to the library, labs, / and campus routes.','orient.s1 指帮助某人熟悉新环境或情况。','学生通过向导熟悉校园。'),C('orient.s2','通用','Before marking the map, orient it so that the printed north arrow points toward the actual north.','标地图之前，先调整地图方向，使印刷的北箭头指向实际的北方。','Before marking the map / orient it / so that the printed north arrow / points toward the actual north.','orient.s2 指确定或调整方向、方位。','地图北箭头与真实北方对齐。')],M('The guide helped the new students orient themselves by hiding the campus map and refusing to explain where anything was.','The guide helped the new students orient themselves by showing key buildings and routes.','orient oneself 是熟悉环境；阻止了解地点与这一含义相反。','distinction'),[Q(1,'What did the guide help students do?','Become familiar with campus places and routes.','Point a north arrow south.','Arrange a mountain-building process.','orient.s1 concerns becoming familiar with a setting.'),Q(2,'How should the map be oriented?','With its north arrow toward actual north.','With its legend covering the north arrow.','With its top always facing the reader regardless of direction.','orient.s2 concerns direction.'),Q(1,'Which sentence uses orient to mean “become familiar”?','The guide helped interns orient themselves to the new office.','She oriented the compass needle toward north.','They ornamented the hall with flowers.','The first sentence describes learning a new setting.','distinction'),Q(2,'What is the central idea of orient in the map example?','Positioning something relative to direction.','Naming the person who plans a meeting.','Giving a decorative object a new label.','The map is adjusted to match geographic north.','meaning')]);
P('oriental','From Middle English and Old French, ultimately Latin orientalis “eastern”; in current English it is suitable for some objects or styles but is widely considered outdated or offensive for people.',[C('oriental.s1','用法','The museum label described the porcelain as an Oriental-style object, while identifying its maker and region more precisely elsewhere.','博物馆标签将这件瓷器描述为东方风格的物品，同时在别处更具体地标出了制作者和产地。','The museum label described the porcelain / as an Oriental-style object / while identifying its maker / and region more precisely elsewhere.','oriental.s1 可用于某些亚洲风格物品，但称呼人时通常过时且冒犯；应具体说明身份或地区。','例句说的是瓷器风格，不是人的身份。','register'),C('oriental.s2','用法','The curator replaced “Oriental communities” with the specific names of the Asian communities represented in the exhibit.','策展人把“东方社群”改成展览所呈现的各亚洲社群的具体名称。','The curator replaced “Oriental communities” / with the specific names / of the Asian communities / represented in the exhibit.','oriental.s2 涉及对人的称谓时应避免笼统标签，改用具体身份或地区称呼。','明确改为社群的具体名称。','register')],M('The guide called every person in the gallery “an Oriental” as a neutral modern label, without asking how they identify.','The guide used each person’s specific identity or regional name and reserved the older term for a relevant object or style.','当代英语中用 Oriental 指人常被视为过时或冒犯，应采用具体称谓。','register'),[Q(1,'What does the first museum label describe with Oriental-style?','The porcelain’s style.','The maker’s personal identity.','The museum visitors as a group.','oriental.s1 is applied to an object or style in this context.','usage'),Q(2,'What wording did the curator choose for the communities?','Their specific community names.','One broad label for all Asian people.','A name based only on the exhibit building.','Specific names avoid an outdated blanket label.'),Q(1,'Which use is most appropriate in the example?','Describing a historical object’s style with context.','Calling a person “an Oriental” as a neutral modern term.','Using the word as a person’s chosen name without checking.','The term can describe some objects or styles but is problematic for people.','register'),Q(2,'How should a writer refer to people instead?','Use the specific identity or regional name when known.','Use one outdated label for everyone.','Avoid naming any community at all.','Current usage favors specific self-identification or regional wording.','word-choice')]);
P('orientate','From orient + -ate, formed on the model of orient; it means to establish direction or help someone become familiar with a new place.',[C('orientate.s1','通用','The trail sign orientated hikers toward the river crossing before the path split into two routes.','步道标牌在岔路口之前为徒步者指明了通往河流渡口的方向。','The trail sign orientated hikers / toward the river crossing / before the path split / into two routes.','orientate.s1 指确定方向，或帮助某人熟悉环境。','标牌为徒步者指路。','word-formation')],M('The trail sign orientated hikers by pointing them away from every marked route and giving no location information.','The trail sign orientated hikers by showing the direction of the river crossing.','orientate 表示定向或帮助熟悉位置，而不是令方向更混乱。','meaning'),[Q(1,'Where did the sign orientate hikers?','Toward the river crossing.','Toward an unmarked destination in the opposite direction.','Toward the conference room.','orientate.s1 describes giving hikers a direction.'),Q(1,'Which action can orientate a newcomer?','Showing the entrance, exits, and key rooms.','Removing all signs from the building.','Changing the spelling of the town.','Helping someone learn a place’s layout is orientating them.'),Q(1,'Which word is closest in meaning to orientate here?','direct','decorate','mislead','The sign directs hikers toward a landmark.'),Q(1,'How is orientate formed?','orient + -ate','orientation + -ly','origin + -al','The verb is built from orient with -ate.','word-formation')]);
P('orientation','From orient + -ation; it means the direction in which something faces, or an introductory process that helps someone understand a new setting.',[C('orientation.s1','通用','The satellite’s orientation changed after its control system turned the solar panels toward the Sun.','控制系统将太阳能板转向太阳后，卫星的朝向发生了变化。','The satellite’s orientation changed / after its control system / turned the solar panels / toward the Sun.','orientation.s1 指物体面对或排列的方向。','太阳能板转向改变了卫星的朝向。'),C('orientation.s1','教育','During employee orientation, new staff learned the safety rules, reporting lines, and layout of the building.','在员工入职介绍期间，新员工了解了安全规定、汇报关系和大楼布局。','During employee orientation / new staff learned / the safety rules, reporting lines, / and layout of the building.','orientation.s1 指帮助新人了解新工作、课程或环境的介绍活动。','新员工通过介绍熟悉规则和场所。')],M('At employee orientation, the new staff were deliberately kept unaware of safety rules, reporting lines, and the building layout.','Employee orientation introduced new staff to safety rules, reporting lines, and the building.','orientation 的入职介绍帮助新人了解工作环境，而不是隐瞒关键信息。','distinction'),[Q(1,'What changed the satellite’s orientation?','The panels were turned toward the Sun.','The employees attended an induction.','The building received new safety rules.','orientation.s1 is the satellite’s facing direction.'),Q(1,'What did new staff learn during orientation?','Safety rules, reporting lines, and the building layout.','How to turn a satellite toward the Sun.','The etymology of the word organizer.','orientation.s1 is an introductory session.'),Q(1,'Which is an example of orientation as direction?','A wind vane’s position relative to north.','A new employee’s first-day briefing.','A list of staff members.','The wind vane example describes facing direction.'),Q(1,'Which is an example of employee orientation?','An introduction to workplace procedures and facilities.','A compass pointing northeast.','An annual budget spreadsheet alone.','An induction familiarizes new workers with the setting.','meaning')]);
P('origin','From Latin origo, origin- “beginning, source,” from oriri “to rise”; it refers to where, when, or why something begins, and can also mean a person’s background.',[C('origin.s1','通用','Researchers traced the origin of the spring to rainwater filtering through limestone hills.','研究人员追溯出泉水源自雨水渗过石灰岩山丘。','Researchers traced the origin of the spring / to rainwater / filtering through / limestone hills.','origin.s1 指某事物开始的地点、时间或原因。','研究人员找到了泉水的来源。'),C('origin.s2','社会','Although she grew up abroad, she spoke proudly about her family’s origin in a small coastal town.','尽管她在国外长大，她仍自豪地谈起家族来自一座海滨小镇。','Although she grew up abroad / she spoke proudly / about her family’s origin / in a small coastal town.','origin.s2 可指一个人的家族或社会背景、出身。','句子说明家族来自哪里。')],M('The spring’s origin was traced to a sealed factory tank even though samples showed it came from rain filtering through limestone.','The spring’s origin was traced to rainwater filtering through the limestone hills.','来源解释应与证据显示的实际起点相符。','meaning'),[Q(1,'Where did the spring originate?','In rainwater filtering through limestone hills.','In a family’s coastal background.','In a sealed tank with no connection to the site.','origin.s1 is the source from which the spring begins.'),Q(2,'What does family’s origin refer to here?','Its background or place of origin.','The spring’s chemical formula.','A researcher’s job title.','origin.s2 concerns family background.'),Q(1,'Which question asks about origin as a source?','Where did this custom begin?','What color is the custom’s logo?','How many people attended today?','Asking where something began asks about its origin.'),Q(2,'Which phrase can refer to someone’s background?','family origin','panel orientation','employee orientation','family origin can describe a person’s background.','collocation')]);
P('original','From Latin originalis “of the beginning,” from origo “source”; as an adjective it describes something new or not copied, and as a noun it can mean the first version.',[C('original.s1','艺术','The artist submitted an original design that she had drawn herself rather than tracing an existing poster.','这位艺术家提交了自己绘制的原创设计，而不是临摹现有海报。','The artist submitted an original design / that she had drawn herself / rather than tracing / an existing poster.','original.s1 作形容词，指原创的、非复制的。','设计由艺术家自己创作。'),C('original.s2','出版','The archive preserved the original of the letter, while researchers read digital copies in the study room.','档案馆保存了这封信的原件，研究人员则在阅览室阅读数字副本。','The archive preserved the original of the letter / while researchers read / digital copies / in the study room.','original.s2 作名词，指最初的版本或原件。','信件原件被保存，其他人阅读副本。')],M('The gallery called the traced poster design original even though it copied every line from an existing work.','The gallery called the artist’s independently created design original.','照搬已有作品的设计不是原创。','distinction'),[Q(1,'Why was the design original?','The artist created it herself.','She traced every line from a poster.','It was a digital copy of an old letter.','original.s1 means newly created rather than copied.'),Q(2,'What did the archive preserve?','The first, physical version of the letter.','Only a traced poster.','A newly invented spelling.','original.s2 is the earliest version or source item.'),Q(1,'Which is an original work?','A drawing created independently by its artist.','A drawing copied line for line from another artist.','A scan of someone else’s drawing.','Original work is not copied from an existing piece.'),Q(2,'In “the original was kept in the archive,” what is original?','A noun for the first version or source item.','An adverb meaning at first.','A verb meaning to begin.','Here original names the preserved item.','word-choice')]);
P('originality','From original + -ity, naming the quality or capacity of being original.',C('originality.s1','艺术','The judges praised the designer’s originality because the familiar materials were combined in an unexpected way.','评委称赞设计师的独创性，因为常见材料被以出人意料的方式组合起来。','The judges praised the designer’s originality / because familiar materials / were combined / in an unexpected way.','originality.s1 指独创性，尤其是产生新颖想法或作品的能力。','评委认可设计的新颖组合。','word-formation'),M('The judges praised the designer’s originality for copying another artist’s layout exactly without adding any new idea.','The judges praised the designer’s originality for combining familiar materials in a fresh way.','原样照抄没有体现独创性。','distinction'),[Q(1,'Why did the judges praise the designer?','The materials were combined unexpectedly.','The layout was copied exactly.','The designer used no materials.','originality.s1 concerns a fresh and independent approach.'),Q(1,'Which work shows originality?','A new solution that combines familiar tools in a surprising way.','An exact duplicate with no changes.','A blank page submitted as a copy.','Originality involves novelty or independent creativity.','meaning'),Q(1,'What quality does originality name?','The quality of being original.','The act of arranging rooms.','The direction something faces.','The noun names a quality of original work.'),Q(1,'How is originality formed?','original + -ity','origin + past -ed','orient + -ate','-ity forms a noun naming a quality from original.','word-formation')]);
P('originally','From original + -ly; it is an adverb meaning at first or in the beginning, before later changes.',C('originally.s1','通用','The trail originally ended at the old bridge, but a later extension carried it to the visitor center.','这条步道最初止于老桥，但后来延伸到了游客中心。','The trail originally ended / at the old bridge / but a later extension / carried it to the visitor center.','originally.s1 表示最初、起初，常与后来的变化形成对照。','最初的终点与后来延伸后的终点不同。','word-formation'),M('The trail originally ended at the visitor center, and only later was it extended back to the old bridge.','The trail originally ended at the old bridge and was extended to the visitor center later.','originally 指较早的状态；例句把先后顺序倒置了。','usage'),[Q(1,'Where did the trail first end?','At the old bridge.','At the visitor center.','At a newly built station.','originally.s1 means at first.'),Q(1,'What happened later?','The trail was extended to the visitor center.','The old bridge was built before the trail existed.','The path was never changed.','The sentence contrasts the original endpoint with a later extension.'),Q(1,'Which phrase is closest to originally?','at first','in the end','from time to time','originally refers to an earlier state.','meaning'),Q(1,'How is originally formed?','original + -ly','origin + -ity','organize + -er','-ly forms an adverb from original.','word-formation')]);
P('originate','From Latin originari “to arise, begin,” from origo “source”; it means to begin or be created at a particular place, time, or source.',[C('originate.s1','通用','The practice of leaving a light on for arriving guests originated in the village’s winter travel custom.','为归来的客人留灯的做法源自这个村庄冬季出行的习俗。','The practice of leaving a light on / for arriving guests / originated in / the village’s winter travel custom.','originate.s1 指起源于某个地点、时间或来源。','习俗的起点是村庄的冬季出行传统。')],M('The village custom originated in a recent television advert, although records show it was practiced centuries earlier.','The custom originated in an older village practice recorded centuries before the advert.','时间证据表明习俗早于广告，不能说它起源于广告。','usage'),[Q(1,'What did the guest-lighting practice originate in?','A winter travel custom in the village.','A later television advert.','A satellite’s solar panels.','originate.s1 identifies the practice’s source.'),Q(1,'Which sentence uses originate correctly?','The festival originated in a harvest celebration.','The festival originated its visitors toward the exit.','The festival was an original of the mountain.','originate can mean begin or arise from a source.','usage'),Q(1,'What does “the custom originated in the village” mean?','The custom began there.','The custom was copied there but began elsewhere.','The custom was canceled there.','originate in marks a point of beginning.'),Q(1,'Which form is the verb related to origin?','originate','originality','originally','originate is the verb meaning to begin or arise.','word-formation')]);
P('originating in','From originate + in; this phrase identifies the place, time, or source where something began.',C('originating in.s1','通用','The weaving pattern, originating in the mountain villages, spread to city workshops through traveling traders.','这种编织图案源自山村，后来经由流动商贩传播到城市作坊。','The weaving pattern / originating in the mountain villages / spread to city workshops / through traveling traders.','originating in.s1 用来说明事物起源的地点或来源。','分词短语交代图案起源于何处。','word-formation'),M('The weaving pattern was described as originating in the mountain villages even though records show it was invented in a city workshop.','The weaving pattern was described as originating in the city workshop where records first document it.','起源地点应与可核查的历史记录相符。','meaning'),[Q(1,'Where was the weaving pattern said to begin?','In the mountain villages.','In the city workshops only.','In a traveling trader’s cart.','originating in.s1 specifies a source location.'),Q(1,'Which phrase correctly completes “The custom, ___, later spread abroad”?','originating in the port city','orienting in the port city','ornamental in the port city','originating in identifies where it began.','collocation'),Q(1,'What does originating in add to the sentence?','The place where the pattern began.','The name of the trader.','The date when the city closed.','The phrase marks an origin or source.'),Q(1,'Which verb does originating come from?','originate','ornament','organize','The participle is formed from the verb originate.','word-formation')]);
P('originator','From originate + -or; it names the person who first creates or starts an idea, plan, or movement.',C('originator.s1','通用','The originator of the neighborhood exchange proposed the idea and wrote the first rules for swapping tools.','社区互换项目的发起人提出了这个想法，并写下了交换工具的第一版规则。','The originator of the neighborhood exchange / proposed the idea / and wrote the first rules / for swapping tools.','originator.s1 指最初提出想法或创立计划的人。','此人提出想法并撰写首版规则。','word-formation'),M('The originator of the exchange joined only after the complete plan had been created by someone else.','The originator proposed the exchange before its rules and structure were developed.','originator 是最初发起者，不是事后加入者。','distinction'),[Q(1,'What did the exchange’s originator do?','Proposed the idea and wrote the first rules.','Joined after another person made the full plan.','Only borrowed a tool once.','originator.s1 is the person who first starts an idea.'),Q(1,'Who is the originator of a campaign?','The person who first proposes and launches it.','A person who sees an advertisement later.','A person who attends but takes no part.','The originator initiates the campaign.'),Q(1,'Which noun is closest in meaning to originator?','initiator','spectator','recipient','An originator begins or launches something.'),Q(1,'Which suffix helps form originator?','-or','-less','-ward','-or forms an agent noun from originate.','word-formation')]);
P('orleans','The name of the French city of Orléans is recorded in its official city history; the English spelling omits the accent, while the exact historical evolution of the name is not asserted here.',C('orleans.s1','地名','The choir traveled to Orléans in central France to perform near the Loire, and its itinerary listed the city as Orleans in English.','合唱团前往法国中部的奥尔良，在卢瓦尔河附近演出；行程单的英文部分将这座城市写作 Orleans。','The choir traveled to Orléans / in central France / to perform near the Loire / and its itinerary listed the city as Orleans in English.','orleans.s1 是法国城市 Orleans（法语常写作 Orléans）的专名。','句子明确指卢瓦尔河畔的法国城市。','capitalization'),M('The itinerary said the choir visited Orleans, a city in central France, but the note identified it as a coastal town in Australia.','The itinerary identified Orleans as the French city in central France near the Loire.','例句中的专名所指应保持一致；Orleans 是法国城市名。','meaning'),[Q(1,'Where did the choir travel?','To the French city of Orléans near the Loire.','To a coastal city in Australia.','To a conference room called Orient.','orleans.s1 refers to the French city.'),Q(1,'Which place is Orleans in this example?','A city in central France.','A mountain range formed by plate collision.','A type of decorative carving.','The context locates Orleans in France.'),Q(1,'Which sentence refers to Orleans as a proper name?','They visited Orleans in France.','The committee organized its files.','Her original drawing won a prize.','Orleans names a specific city.'),Q(1,'Why may French spelling show an accent?','The city’s French name is commonly written Orléans.','Every English place name must include an accent.','The word is an adverb ending in -ly.','The French form retains the accent in the city name.','capitalization')]);
P('ornament','From Latin ornamentum “equipment, adornment,” from ornare “to equip, adorn”; it can name a decorative object or detail, or mean to decorate something.',[C('ornament.s1','家居','A small glass ornament hung from the evergreen branch and caught the light from the window.','一件小玻璃装饰物挂在常青树枝上，映着窗户透进来的光。','A small glass ornament / hung from the evergreen branch / and caught the light / from the window.','ornament.s1 指用于装饰的小物件。','玻璃小物挂在树枝上作为装饰。'),C('ornament.s2','艺术','The carved stone ornament above the doorway showed leaves and birds in a repeating pattern.','门口上方雕刻的石饰以重复图案呈现了树叶和鸟。','The carved stone ornament / above the doorway / showed leaves and birds / in a repeating pattern.','ornament.s2 指建筑或物品上的装饰性细节。','石雕是门上的装饰细节。'),C('ornament.s3','通用','The composer ornamented the melody with brief turns that decorated the main notes without changing its shape.','作曲家用短小的回旋音装饰旋律，在不改变旋律轮廓的情况下修饰了主音。','The composer ornamented the melody / with brief turns / that decorated the main notes / without changing its shape.','ornament.s3 作动词，表示为某物增添装饰或修饰。','短小音型修饰主旋律。')],M('The composer ornamented the melody by removing every decorative flourish and leaving only the bare notes.','The composer ornamented the melody by adding brief turns around its main notes.','ornament 作动词表示增加装饰；删去装饰与此相反。','distinction'),[Q(1,'What hung from the evergreen branch?','A small glass decorative object.','A carved doorway.','A musical phrase.','ornament.s1 is a decorative item.'),Q(2,'What was the stone ornament?','A carved decorative detail above the doorway.','A glass object hanging on a tree.','A person who started a musical movement.','ornament.s2 refers to decorative detail.'),Q(3,'How did the composer ornament the melody?','By adding brief turns around the main notes.','By deleting every note.','By changing the tune into a map.','ornament.s3 is the verb meaning to decorate.'),Q(1,'Which object is an ornament?','A small decorative glass figure on a tree.','A plain tool kept for work only.','A route schedule for hikers.','An ornament is a decorative object.','meaning')]);
P('ornamental','From ornament + -al; it describes something intended mainly for decoration, and as a noun can refer to a plant grown for its appearance.',[C('ornamental.s1','建筑','The garden gate has ornamental ironwork shaped into leaves, while the plain hinges carry the gate’s weight.','花园门上的装饰性铁艺被做成树叶形状，而朴素的铰链承担着门的重量。','The garden gate has ornamental ironwork / shaped into leaves / while the plain hinges / carry the gate’s weight.','ornamental.s1 指主要用于装饰而非实用功能的。','铁艺负责装饰，铰链负责支撑。'),C('ornamental.s2','园艺','The nursery sells ornamental grasses for borders, chosen for their color and form rather than for food.','苗圃出售观赏草用于花境，挑选依据是颜色和形态，而不是食用价值。','The nursery sells ornamental grasses / for borders / chosen for their color and form / rather than for food.','ornamental.s2 作名词，指因观赏价值而种植的植物。','这些草因外观而种植。')],M('The garden described a plain load-bearing hinge as ornamental even though it had no decorative feature and served only a structural purpose.','The garden described the leaf-shaped ironwork as ornamental because it was added for decoration.','ornamental 表示装饰用途；纯粹承担结构功能的铰链并非装饰物。','distinction'),[Q(1,'What is ornamental about the gate?','The leaf-shaped ironwork.','The hinges that carry the gate’s weight.','The garden’s water supply.','ornamental.s1 is decorative.'),Q(2,'Why are the grasses ornamental?','They are chosen for appearance rather than food.','They are harvested only for grain.','They support the gate hinges.','ornamental.s2 names plants valued for display.'),Q(1,'Which object is ornamental?','A carved panel added for appearance.','A hidden bolt whose only job is fastening.','A plain pipe that carries water.','An ornamental object is mainly decorative.','meaning'),Q(2,'Which phrase can be a noun meaning a decorative plant?','an ornamental','an organizer','an originator','Ornamental can be used as a noun for a plant grown for appearance.','word-choice')]);
P('ornamentation','From ornament + -ation; it names the objects, patterns, or details used to decorate something.',[C('ornamentation.s1','艺术','The manuscript’s gold-leaf ornamentation framed the title but left the text itself easy to read.','手稿的金箔装饰围绕着标题，同时让正文保持清晰易读。','The manuscript’s gold-leaf ornamentation / framed the title / but left the text itself / easy to read.','ornamentation.s1 指用于装饰的图案、细节或装饰物。','金箔细节装点标题周围。','word-formation')],M('The manuscript’s ornamentation consisted of plain unmarked margins with no pattern, color, or decorative detail.','The manuscript’s ornamentation consisted of gold-leaf patterns around the title.','没有装饰图案或细节就谈不上 ornamentation。','meaning'),[Q(1,'What did the gold-leaf ornamentation do?','Framed the manuscript’s title.','Covered and obscured every line of text.','Changed the title’s meaning.','ornamentation.s1 means decorative details or patterns.'),Q(1,'Which is an example of ornamentation?','Repeated carved patterns around a doorway.','A plain structural support with no decoration.','A schedule listing meeting times.','Ornamentation is decorative patterning or detail.'),Q(1,'What does ornamentation name?','Decorative details or patterns collectively.','The person who starts a project.','A compass direction.','The noun refers to applied decoration.'),Q(1,'Which word is ornamentation formed from?','ornament','origin','orphan','The noun is built from ornament with -ation.','word-formation')]);
P('ornate','From Latin ornatus “adorned,” past participle of ornare “to equip, adorn”; it describes something elaborately decorated.',C('ornate.s1','建筑','The ornate ceiling was covered with painted vines, gilded borders, and carefully carved figures.','华丽的天花板上绘有藤蔓、镀金边饰和精细雕刻的人物。','The ornate ceiling / was covered with painted vines / gilded borders / and carefully carved figures.','ornate.s1 指装饰繁复、细节丰富的。','藤蔓、镀金边饰和雕刻构成繁复装饰。'),M('The room was called ornate even though its ceiling and walls were completely bare and undecorated.','The room was called ornate because its ceiling and walls carried elaborate painted and carved details.','ornate 描述装饰繁复；空白无饰的房间不符合此义。','meaning'),[Q(1,'Why was the ceiling ornate?','It had painted, gilded, and carved details.','It was bare and undecorated.','It was hidden beneath a plain roof.','ornate.s1 means elaborately decorated.'),Q(1,'Which room is ornate?','One with intricate carvings and gilded patterns.','One with empty walls and no details.','One used only as a storage space.','The first room has elaborate decoration.'),Q(1,'Which word is closest in meaning to ornate?','elaborately decorated','unadorned','unfinished','Ornate describes elaborate decoration.'),Q(1,'Which feature best supports calling a ceiling ornate?','Many detailed painted and carved motifs.','A smooth undecorated surface.','A low heating bill.','Complex decorative details make it ornate.','meaning')]);
P('ornithology','From Greek ornitho- “bird” + -logia “study”; it is the scientific study of birds, including their classification, behavior, and ecology.',C('ornithology.s1','科学','Her ornithology project compared nesting behavior in two shorebird species across protected wetlands.','她的鸟类学项目比较了受保护湿地中两种滨鸟的筑巢行为。','Her ornithology project / compared nesting behavior / in two shorebird species / across protected wetlands.','ornithology.s1 指研究鸟类及其分类、行为和生态的科学。','项目研究两种鸟的筑巢行为。','word-formation'),M('The ornithology project studied only mineral crystal formation and collected no information about birds.','The ornithology project studied nesting behavior in shorebird species.','ornithology 专指鸟类学，研究对象是鸟。','meaning'),[Q(1,'What did the ornithology project compare?','Nesting behavior in two shorebird species.','The crystal structure of minerals.','The orientation of a satellite.','ornithology.s1 is the scientific study of birds.'),Q(1,'Which subject belongs to ornithology?','How migrating birds choose stopover wetlands.','How mountain ranges form from plate collisions.','How a company organizes its budget.','Bird migration is a topic in ornithology.'),Q(1,'What is the focus of ornithology?','Birds and their biology or behavior.','All mammals equally.','Only decorative objects.','The term names the scientific study of birds.'),Q(1,'Which roots build ornithology?','Greek ornitho- “bird” + -logia “study”','Latin origo “source” + -ly','French organiser + -er','The compound combines the bird root and study suffix.','word-formation')]);
P('orogeny','From Greek oro- “mountain” + -geny “formation”; the geological process of mountain building, especially through crustal deformation and plate convergence.',C('orogeny.s1','地质','Geologists linked the uplifted ridge to an ancient orogeny in which two crustal plates compressed the region.','地质学家将这条隆起山脊与一次古老的造山运动联系起来，当时两块地壳板块挤压了该地区。','Geologists linked the uplifted ridge / to an ancient orogeny / in which two crustal plates / compressed the region.','orogeny.s1 指造山过程，通常涉及地壳变形或板块汇聚。','板块挤压与山脊隆起相联系。','word-formation'),M('The geologists called the ridge’s formation an orogeny even though no crustal deformation or mountain building had occurred.','The geologists called the plate-driven mountain-building event an orogeny.','orogeny 是造山过程，不能用于没有造山作用的事件。','meaning'),[Q(1,'What caused the ancient orogeny in the example?','Compression between two crustal plates.','The decoration of a manuscript.','A bird’s nesting behavior.','orogeny.s1 concerns mountain building by crustal processes.'),Q(1,'Which event is an orogeny?','Converging plates deforming crust and raising a mountain belt.','A river depositing sand on a flat beach.','A curator arranging objects in a gallery.','Orogeny is mountain-building geology.'),Q(1,'What does orogeny mean?','The process of mountain formation.','The study of birds.','A person who begins a project.','The term denotes mountain building.'),Q(1,'What do oro- and -geny contribute?','“Mountain” + “formation.”','“Bird” + “study.”','“Beginning” + “decoration.”','The word combines the mountain root with a formation suffix.','word-formation')]);
P('orphan','From Greek orphanos “bereft of parents,” via Latin and French; as a noun it is a child whose parents have died or who has lost parental care, and as a verb it can mean to leave a child without parents.',[C('orphan.s1','社会','After both parents died, the child became an orphan and was placed with relatives while guardianship was arranged.','父母双亡后，这个孩子成了孤儿；在安排监护期间，他被安置在亲属家中。','After both parents died / the child became an orphan / and was placed with relatives / while guardianship was arranged.','orphan.s1 作名词，指父母已去世或失去父母照料的孩子。','父母去世后，孩子需要监护安排。'),C('orphan.s2','社会','The flood orphaned two young siblings when their parents were lost in the disaster.','洪灾夺去了两个孩子的父母，使他们成了孤儿。','The flood orphaned two young siblings / when their parents / were lost / in the disaster.','orphan.s2 作动词，指使孩子失去父母，通常因父母去世。','灾害导致孩子失去父母。')],M('The child was called an orphan even though both parents were alive, present, and actively caring for the child.','The child was called an orphan after both parents died and care arrangements were needed.','orphan 的此义涉及失去父母或父母照料，例句里的情况不符合。','meaning'),[Q(1,'Why did the child become an orphan?','Both parents died.','The child moved to a new school.','A guardian arranged a visit.','orphan.s1 refers to a child who has lost parents or parental care.'),Q(2,'What did the flood do to the siblings?','It left them without their parents.','It appointed them as guardians.','It moved their parents to a new house.','orphan.s2 is the verb meaning to make a child an orphan.'),Q(1,'Which child is an orphan in the example?','A child whose parents have died.','A child whose parents are at work for one afternoon.','A child who changed classrooms.','The defining context is loss of parents or parental care.'),Q(2,'How is orphan used in “The disaster orphaned them”?','As a verb meaning it left them without parents.','As an adjective meaning elaborately decorated.','As a noun for a mountain-building event.','Here orphan is a transitive verb.','word-choice')]);

})();
